import fs from 'node:fs/promises';import path from 'node:path';import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const ui={"path":"ASTRA-Frontend-latest/src/pages/change-workspace.tsx","before":"import { hasFullAccess } from './role-access';\nimport ProfileIdentity from './profile-identity';\nimport { uiLabel } from './ui-label';\n'use client';\nimport './change-detail-layout.css';\nimport { reviewedFetch } from './reviewed-fetch';\nimport ExpandablePanel from './expandable-panel';\nimport AdministrationOversight from './administration-oversight';\nimport WorkspaceNavigation from './workspace-navigation';\nimport { extensionLinks } from './workspace-navigation-data';\nimport MailTimeline from './mail-timeline';\nimport ChangeGovernancePanel from './change-governance-panel';\nimport ChangeReviewWorkspace from './change-review-workspace';\nimport ChangePlanTemplateDialog from './change-plan-template-dialog';\nimport { canCreateChangePlan, canSaveChangePlanDirectly, changePlanFromForm, applyChangePlanToForm, type ChangePlanData, type SavedChangePlan } from './change-plan-model';\nimport { canReviewChangeRequests } from './change-review-access';\nimport type {\n  ChangeTemplate,\n  GovernanceConfig,\n} from './admin/change-governance/governance-administration';\nimport Link from '../navigation/link';\nimport { FormEvent, useCallback, useEffect, useState } from 'react';\nimport { useRouter, useSearchParams } from '../navigation/hooks';\nimport BrandMark from './brand-mark';\nimport NotificationCenter from './notification-center';\nimport UiIcon, { type IconName } from './ui-icon';\n\ntype Row = Record<string, unknown>;\ninterface Session {\n  csrfToken: string;\n  user: {\n    id: string;\n    displayName: string;\n    roles: string[];\n    permissions?: string[];\n    workScope?: string;\n    workspace?: string;\n    changeAccess?: string;\n  };\n}\ninterface Options {\n  clients: Row[];\n  sites: Row[];\n  contacts: Row[];\n  departments: Row[];\n  users: Row[];\n  tickets: Row[];\n  categories: string[];\n  types: string[];\n  risks: string[];\n  statuses: string[];\n  emailEnabled: boolean;\n  changeMailbox: string;\n}\nconst label = uiLabel;\nconst date = (v: unknown) => (v ? new Date(String(v)).toLocaleString() : '—');\nasync function fileToBase64(file: File) {\n  return new Promise<string>((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onload = () => resolve(String(reader.result).split(',')[1] ?? '');\n    reader.onerror = () => reject(new Error('Unable to read attachment.'));\n    reader.readAsDataURL(file);\n  });\n}\nfunction parseExternalStakeholder(value: string) {\n  const match = value.match(/^(.+?)\\s*<([^<>]+)>$/);\n  return match\n    ? { name: match[1].trim(), email: match[2].trim(), role: 'STAKEHOLDER' }\n    : { email: value, role: 'STAKEHOLDER' };\n}\n\nexport default function ChangeWorkspace({\n  view = 'dashboard',\n  changeId,\n}: {\n  view?: 'dashboard' | 'new' | 'detail';\n  changeId?: string;\n}) {\n  const router = useRouter();\n  const searchParams = useSearchParams();\n  const [session, setSession] = useState<Session>();\n  const reviewingChanges = view === 'dashboard' && searchParams.get('reviewCM') === '1';\n  const canReviewCM = canReviewChangeRequests(session?.user.roles ?? []);\n  const [menu, setMenu] = useState(false);\n  const [options, setOptions] = useState<Options>();\n  const [data, setData] = useState<Row>();\n  const [error, setError] = useState('');\n  const [notice, setNotice] = useState('');\n  const [busy, setBusy] = useState(false);\n  const [revision, setRevision] = useState(0);\n  const [creatingTemplate, setCreatingTemplate] = useState(false);\n  const [templateRevision, setTemplateRevision] = useState(0);\n  function templateSaved(result: { status: string }) {\n    setCreatingTemplate(false); setTemplateRevision(value => value + 1);\n    setNotice(result.status === 'APPROVED' ? 'Template saved and available in saved plans.' : 'Template submitted for approval. Your team lead, manager or administrator can review it in Review CM > Templates.');\n  }\n  const request = useCallback(\n    async (path: string, init?: RequestInit) => {\n      const r = await reviewedFetch(`/api${path}`, {\n        ...init,\n        cache: 'no-store',\n        headers: {\n          ...(init?.body ? { 'content-type': 'application/json' } : {}),\n          ...(session ? { 'x-csrf-token': session.csrfToken } : {}),\n          ...init?.headers,\n        },\n      });\n      const body = await r.json().catch(() => ({}));\n      if (!r.ok) throw new Error(body.error?.message ?? 'Request failed.');\n      return body;\n    },\n    [session],\n  );\n  useEffect(() => {\n    let live = true;\n    void fetch('/api/auth/me', { cache: 'no-store' })\n      .then(async (r) => {\n        if (!r.ok) throw new Error('Sign in to open Change Management.');\n        const s = (await r.json()) as Session;\n        if (s.user.changeAccess === 'NONE' && !hasFullAccess(s.user.roles))\n          throw new Error(\n            'Change Management has not been enabled for your account.',\n          );\n        if (live) setSession(s);\n      })\n      .catch((e) => live && setError(e.message));\n    return () => {\n      live = false;\n    };\n  }, []);\n  useEffect(() => {\n    if (!session) return;\n    if (reviewingChanges) { setError(''); setNotice(''); return; }\n    let live = true;\n    void Promise.all([\n      request('/changes/options'),\n      view === 'dashboard'\n        ? Promise.all([\n            request('/changes/dashboard'),\n            request('/changes?pageSize=50'),\n            request('/changes/calendar'),\n          ]).then(([dashboard, list, calendar]) => ({\n            dashboard,\n            list,\n            calendar,\n          }))\n        : view === 'detail' && changeId\n          ? request(`/changes/${changeId}`)\n          : Promise.resolve({}),\n    ])\n      .then(([o, d]) => {\n        if (live) {\n          setOptions(o as Options);\n          setData(d as Row);\n        }\n      })\n      .catch((e) => live && setError(e.message));\n    return () => {\n      live = false;\n    };\n  }, [session, request, view, changeId, revision, reviewingChanges]);\n  async function submit(path: string, payload: Row, method = 'POST') {\n    setBusy(true);\n    setError('');\n    try {\n      const result = (await request(path, {\n        method,\n        body: JSON.stringify(payload),\n      })) as Row;\n      setNotice('Saved successfully.');\n      setRevision((x) => x + 1);\n      return result;\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(false);\n    }\n  }\n  async function create(e: FormEvent<HTMLFormElement>) {\n    e.preventDefault();\n    const f = new FormData(e.currentTarget);\n    const attachmentFiles = f\n      .getAll('attachments')\n      .filter(\n        (value): value is File => value instanceof File && value.size > 0,\n      );\n    if (\n      attachmentFiles.length > 10 ||\n      attachmentFiles.some((file) => file.size > 5 * 1024 * 1024)\n    ) {\n      setError('Add up to 10 attachments, with a maximum of 5 MB per file.');\n      return;\n    }\n    const attachments = await Promise.all(\n      attachmentFiles.map(async (file) => ({\n        fileName: file.name,\n        contentType: file.type || 'application/octet-stream',\n        contentBase64: await fileToBase64(file),\n      })),\n    );\n    const externalStakeholders = String(f.get('externalStakeholders') ?? '')\n      .split(/[\\n,;]+/)\n      .map((entry) => entry.trim())\n      .filter(Boolean)\n      .map(parseExternalStakeholder);\n    const result = await submit('/changes', {\n      clientId: f.get('clientId'),\n      siteId: f.get('siteId') || undefined,\n      departmentId: f.get('departmentId') || undefined,\n      title: f.get('title'),\n      description: f.get('description'),\n      category: f.get('category'),\n      changeType: f.get('changeType'),\n      risk: f.get('risk'),\n      impact: f.get('impact'),\n      outageExpected: f.get('outageExpected') === 'true',\n      downtimeMinutes: Number(f.get('downtimeMinutes') || 0),\n      reason: f.get('reason'),\n      businessJustification: f.get('businessJustification'),\n      implementationPlan: f.get('implementationPlan'),\n      testPlan: f.get('testPlan'),\n      rollbackPlan: f.get('rollbackPlan'),\n      communicationPlan: f.get('communicationPlan'),\n      clientNotificationEnabled: f.get('clientNotificationEnabled') === 'true',\n      ownerUserId: f.get('ownerUserId') || undefined,\n      plannedStart: f.get('plannedStart')\n        ? new Date(String(f.get('plannedStart'))).toISOString()\n        : undefined,\n      plannedEnd: f.get('plannedEnd')\n        ? new Date(String(f.get('plannedEnd'))).toISOString()\n        : undefined,\n      stakeholderContactIds: f.getAll('stakeholderContactIds').map(String),\n      externalStakeholders,\n      attachments,\n    });\n    if (result?.id) router.push(`/changes/${String(result.id)}?workspace=${encodeURIComponent(selectedWorkspace)}`);\n  }\n  async function logout() {\n    await request('/auth/logout', { method: 'POST' });\n    router.push('/');\n  }\n  const detail = data as\n    | {\n        change?: Row;\n        teams?: Row[];\n        tasks?: Row[];\n        approvals?: Row[];\n        updates?: Row[];\n        links?: Row[];\n        history?: Row[];\n        communications?: Row[];\n      }\n    | undefined;\n  const isAdmin = hasFullAccess(session?.user.roles) ?? false;\n  const readOnly = session?.user.workspace === 'admin';\n  const isManagement =\n    session?.user.roles.includes('MANAGER') ||\n    session?.user.roles.includes('TEAM_LEAD');\n  const allowed = (permission: string) =>\n    isAdmin || session?.user.permissions?.includes(permission);\n  const requestedWorkspace = searchParams.get('workspace');\n  const selectedWorkspace = requestedWorkspace && ['operations', 'management', 'admin'].includes(requestedWorkspace)\n    ? requestedWorkspace\n    : session?.user.workspace ?? (isAdmin ? 'admin' : isManagement ? 'management' : 'operations');\n  const inAdminWorkspace = selectedWorkspace === 'admin';\n  const inManagementWorkspace = selectedWorkspace === 'management';\n  const portalNav: [string, IconName, string][] = inAdminWorkspace\n    ? [\n        ['/admin', 'dashboard', 'Overview'],\n        ['/admin/tickets', 'tickets', 'Tickets'],\n        ['/admin/sla', 'sla', 'SLA Management'],\n        ['/admin/reports', 'reports', 'Reports & Analytics'],\n        ['/admin/users', 'users', 'People & Permissions'],\n        ['/admin/clients', 'clients', 'Clients'],\n        ['/admin/contacts', 'contacts', 'Contacts'],\n        ['/admin/sites', 'sites', 'Sites'],\n        ['/admin/categories', 'categories', 'Categories'],\n        ['/admin/tags', 'tags', 'Tags'],\n        ['/admin/audit-logs', 'audit', 'Audit History'],\n        ['/changes', 'change', 'Change Management'],\n      ]\n    : inManagementWorkspace\n      ? [\n          ['/management', 'dashboard', 'Dashboard'],\n          ['/management/tickets', 'tickets', 'Tickets'],\n          ...(allowed('CATEGORY_MANAGE') ? [['/admin/categories', 'categories', 'Categories'] as [string, IconName, string]] : []),\n          ...(allowed('TAGS_MANAGE') ? [['/admin/tags', 'tags', 'Tags'] as [string, IconName, string]] : []),\n          ...(allowed('AUDIT_VIEW') ? [['/admin/audit-logs', 'audit', 'Audit History'] as [string, IconName, string]] : []),\n          ...(allowed('SLA_MANAGE') || session?.user.roles.includes('TEAM_LEAD')\n            ? ([['/management/sla', 'sla', 'SLA Management']] as [\n                string,\n                IconName,\n                string,\n              ][])\n            : []),\n          ...(allowed('REPORTS_VIEW')\n            ? ([['/management/reports', 'reports', 'Reports & Analytics']] as [\n                string,\n                IconName,\n                string,\n              ][])\n            : []),\n          ['/changes', 'change', 'Change Management'],\n        ]\n      : [\n          ['/operations', 'dashboard', 'Dashboard'],\n          ['/operations/tickets', 'tickets', 'My Tickets'],\n          ...(allowed('TICKETS_TEAM_VIEW')\n            ? ([['/operations/team-tickets', 'team', 'Team Tickets']] as [\n                string,\n                IconName,\n                string,\n              ][])\n            : []),\n          ...(['INTERNAL', 'BOTH', 'ALL'].includes(\n            session?.user.workScope ?? '',\n          )\n            ? ([\n                ['/operations/internal-tickets', 'tickets', 'Internal Tickets'],\n              ] as [string, IconName, string][])\n            : []),\n          ['/changes', 'change', 'Change Management'],\n        ];\n  return (\n    <div className=\"admin-shell ticket-shell change-shell\">\n      <a className=\"skip-link\" href=\"#main\">\n        Skip to content\n      </a>\n      <aside className={`sidebar ${menu ? 'open' : ''}`}>\n        <Link className=\"brand\" href=\"/\">\n          <BrandMark />\n          <span>\n            ASTRA<small>Ticketing System</small>\n          </span>\n        </Link>\n        <p className=\"nav-label\">\n          {inAdminWorkspace\n            ? 'ADMINISTRATION'\n            : inManagementWorkspace\n              ? 'MANAGEMENT'\n              : 'TECHNICIAN PORTAL'}\n        </p>\n        <nav aria-label=\"Portal navigation\">\n          <WorkspaceNavigation\n            links={[...portalNav, ...extensionLinks(session?.user)]}\n            activeHref=\"/changes\"\n            workspace={selectedWorkspace}\n            onNavigate={() => setMenu(false)}\n          />\n        </nav>\n        <div className=\"sidebar-bottom\">\n          <Link href=\"/\">\n            <UiIcon name=\"switch\" /> Switch workspace\n          </Link>\n          <small>\n            <i /> Service desk online\n          </small>\n        </div>\n      </aside>\n      <div className=\"workspace\">\n        <header className=\"topbar\">\n          <button\n            type=\"button\"\n            className=\"menu-button secondary\"\n            aria-expanded={menu}\n            aria-label=\"Toggle navigation\"\n            onClick={() => setMenu(!menu)}\n          >\n            ☰\n          </button>\n          <span className=\"breadcrumb\">\n            <Link href=\"/\" className=\"workspace-home-link\">\n              {inAdminWorkspace\n                ? 'Administration'\n                : inManagementWorkspace\n                  ? 'Management'\n                  : 'Technician Portal'}\n            </Link>{' '}\n            <span>/</span> Change Management\n          </span>\n          {session ? (\n            <div className=\"account\">\n              <ProfileIdentity name={session.user.displayName} workspace={inAdminWorkspace ? 'admin' : inManagementWorkspace ? 'management' : 'operations'} />\n              <NotificationCenter\n                csrfToken={session.csrfToken}\n                ticketBase={\n                  inAdminWorkspace\n                    ? '/admin/ticket'\n                    : inManagementWorkspace\n                      ? '/management/tickets'\n                      : '/operations/tickets'\n                }\n              />\n              <button className=\"secondary\" onClick={() => void logout()}>\n                Sign out\n              </button>\n            </div>\n          ) : null}\n        </header>\n        <main id=\"main\" className=\"content change-workspace-content\">\n          <div className=\"page-heading\">\n            <div>\n              <p className=\"eyebrow\">CONTROLLED SERVICE CHANGE</p>\n              <h1>\n                {reviewingChanges ? 'Review CM' : readOnly && view === 'new'\n                  ? 'Change administration'\n                  : view === 'new'\n                    ? 'Raise a change'\n                    : view === 'detail'\n                      ? `${String(detail?.change?.change_number ?? 'Change record')}`\n                      : 'Change Management'}\n              </h1>\n              <p>\n                {reviewingChanges\n                  ? 'Review waiting change requests and find previous review decisions.'\n                  : readOnly\n                  ? 'Review change records, approvals and history. Configure policy in Service administration.'\n                  : view === 'dashboard'\n                    ? 'Plan, approve, coordinate and verify infrastructure and service changes.'\n                    : view === 'new'\n                      ? 'Document impact, implementation, testing and rollback before approval.'\n                      : 'One controlled record for plan, approvals, teams and evidence.'}\n              </p>\n            </div>\n            <div className=\"v38-row\">\n              {session && view === 'new' && canCreateChangePlan(session.user.roles) ? <button type=\"button\" className=\"primary\" onClick={() => setCreatingTemplate(true)}>New template</button> : null}\n              {session && canReviewCM && view !== 'new' && !reviewingChanges ? <Link className=\"secondary\" href={`/changes?workspace=${encodeURIComponent(selectedWorkspace)}&reviewCM=1`}>Review CM</Link> : null}\n              {reviewingChanges ? <Link className=\"secondary\" href={`/changes?workspace=${encodeURIComponent(selectedWorkspace)}`}>Back to changes</Link> : null}\n              {session && !readOnly && view !== 'new' ? (\n                <Link className=\"primary\" href={`/changes/new?workspace=${encodeURIComponent(selectedWorkspace)}`}>\n                  + Raise change\n                </Link>\n              ) : null}\n            </div>\n          </div>\n          {error ? (\n            <div className=\"notice error\" role=\"alert\">\n              {error}\n            </div>\n          ) : null}\n          {notice ? <div className=\"notice success\">{notice}</div> : null}\n          {session && reviewingChanges ? canReviewCM ? <ChangeReviewWorkspace csrfToken={session.csrfToken} workspace={selectedWorkspace} /> : <p className=\"notice error\" role=\"alert\">Team Lead, Manager or Administrator access is required to review change requests.</p> : null}\n          {readOnly && !reviewingChanges ? <AdministrationOversight /> : null}\n          {view === 'dashboard' && !reviewingChanges ? (\n            <ChangeDashboard data={data} workspace={selectedWorkspace} />\n          ) : null}\n          {session && creatingTemplate ? <ChangePlanTemplateDialog roles={session.user.roles} request={request} onClose={() => setCreatingTemplate(false)} onSaved={templateSaved} /> : null}\n          {view === 'new' && session && !readOnly && options ? (\n            <ChangeForm\n              user={session.user}\n              templateRevision={templateRevision}\n              onTemplateSaved={templateSaved}\n              workspace={selectedWorkspace}\n              options={options}\n              submit={create}\n              busy={busy}\n              request={request}\n              onError={setError}\n            />\n          ) : null}\n          {view === 'detail' && detail?.change && options ? (\n            <ChangeDetail\n              readOnly={readOnly}\n              detail={detail}\n              options={options}\n              busy={busy}\n              submit={submit}\n            />\n          ) : null}\n          {view === 'detail' && detail?.change && session ? (\n            <>\n              <ChangeGovernancePanel\n                change={detail.change}\n                user={session.user}\n                revision={revision}\n                request={request}\n                submit={submit}\n              />\n              <MailTimeline\n                kind=\"changes\"\n                id={String(detail.change.id)}\n                revision={revision}\n              />\n            </>\n          ) : null}\n        </main>\n      </div>\n    </div>\n  );\n}\n\nfunction ChangeDashboard({\n  data,\n  workspace,\n}: {\n  data?: Row;\n  workspace?: string;\n}) {\n  const d = data?.dashboard as Row | undefined;\n  const list = (data?.list as { items?: Row[] } | undefined)?.items ?? [];\n  const calendar = (data?.calendar as Row[] | undefined) ?? [];\n  return (\n    <>\n      <section className=\"metric-grid\">\n        <Metric name=\"Total changes\" value={d?.total} />\n        <Metric name=\"Awaiting approval\" value={d?.awaiting_approval} />\n        <Metric name=\"Scheduled\" value={d?.scheduled} />\n        <Metric name=\"In progress\" value={d?.in_progress} />\n        <Metric name=\"High risk open\" value={d?.high_risk} />\n      </section>\n      <section className=\"change-grid\">\n        <div className=\"panel\">\n          <div className=\"section-heading\">\n            <h2>Change register</h2>\n            <span>{list.length} visible</span>\n          </div>\n          <div className=\"table-wrap\">\n            <table className=\"change-register-table\">\n              <thead>\n                <tr>\n                  <th>Change</th>\n                  <th>Type</th>\n                  <th>Risk</th>\n                  <th>Status</th>\n                  <th>Owner</th>\n                  <th>Window</th>\n                </tr>\n              </thead>\n              <tbody>\n                {list.map((c) => (\n                  <tr key={String(c.id)}>\n                    <td>\n                      <Link\n                        href={`/changes/${String(c.id)}${workspace ? `?workspace=${encodeURIComponent(workspace)}` : ''}`}\n                      >\n                        <strong>{String(c.change_number)}</strong>\n                        <small>{String(c.title)}</small>\n                      </Link>\n                    </td>\n                    <td><span className=\"pill change-type\">{label(c.change_type)}</span></td>\n                    <td>\n                      <span\n                        className={`pill priority-${String(c.risk).toLowerCase()}`}\n                      >\n                        {label(c.risk)}\n                      </span>\n                    </td>\n                    <td>\n                      <span className={`pill change-status-${String(c.status).toLowerCase()}`}>{label(c.status)}</span>\n                    </td>\n                    <td>{String(c.owner_name)}</td>\n                    <td><span className=\"change-window\">{c.planned_start ? date(c.planned_start) : 'Not scheduled'}</span></td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        </div>\n        <div className=\"panel\">\n          <h2>Change calendar</h2>\n          {calendar.length ? (\n            calendar.map((c) => (\n              <Link\n                className=\"calendar-change\"\n                key={String(c.id)}\n                href={`/changes/${String(c.id)}${workspace ? `?workspace=${encodeURIComponent(workspace)}` : ''}`}\n              >\n                <strong>\n                  {String(c.change_number)} · {String(c.title)}\n                </strong>\n                <span>\n                  {date(c.planned_start)} → {date(c.planned_end)}\n                </span>\n              </Link>\n            ))\n          ) : (\n            <p className=\"empty\">No planned change windows yet.</p>\n          )}\n        </div>\n      </section>\n    </>\n  );\n}\nfunction Metric({ name, value }: { name: string; value: unknown }) {\n  return (\n    <div className=\"metric-card\">\n      <span>{name}</span>\n      <strong>{String(value ?? 0)}</strong>\n    </div>\n  );\n}\nfunction Opts({ items }: { items: Row[] }) {\n  return (\n    <>\n      {items.map((x) => (\n        <option key={String(x.id)} value={String(x.id)}>\n          {String(x.name)}\n        </option>\n      ))}\n    </>\n  );\n}\nexport function ChangeForm({\n  user,\n  templateRevision,\n  onTemplateSaved,\n  workspace,\n  options,\n  submit,\n  busy,\n  request,\n  onError,\n}: {\n  options: Options;\n  submit: (e: FormEvent<HTMLFormElement>) => void;\n  busy: boolean;\n  request: (path: string, init?: RequestInit) => Promise<unknown>;\n  onError: (message: string) => void;\n  workspace: string;\n  user: Session['user'];\n  templateRevision: number;\n  onTemplateSaved: (result: { status: string }) => void;\n}) {\n  const [templateSaving, setTemplateSaving] = useState(false);\n  const [selectedTemplate, setSelectedTemplate] = useState('');\n  const [templateDeleting, setTemplateDeleting] = useState(false);\n  const [templateNotice, setTemplateNotice] = useState('');\n  const [clientId, setClientId] = useState('');\n  const [templates, setTemplates] = useState<(ChangeTemplate & { plan?: ChangePlanData })[]>([]);\n  useEffect(() => {\n    let live = true;\n    void Promise.all([request('/change-governance'), request('/changes/templates')])\n      .then(([c, saved]) => {\n        if (!live) return;\n        const plans = (saved as { items: SavedChangePlan[] }).items.map(item => {\n          const plan: ChangePlanData = typeof item.plan === 'string' ? JSON.parse(item.plan) : item.plan;\n          return { id: `plan:${item.id}`, name: item.name, category: plan.category, description: plan.description, implementation_plan: plan.implementationPlan, test_plan: plan.testPlan, rollback_plan: plan.rollbackPlan, active: true, plan };\n        });\n        setTemplates([...(c as GovernanceConfig).templates.filter(t => t.active), ...plans]);\n      })\n      .catch((e) => onError(e.message));\n    return () => {\n      live = false;\n    };\n  }, [request, onError, templateRevision]);\n  const [siteId, setSiteId] = useState('');\n  const [contacts, setContacts] = useState(options.contacts);\n  const [selectedContacts, setSelectedContacts] = useState<string[]>([]);\n  const [contactToAdd, setContactToAdd] = useState('');\n  const [showContactForm, setShowContactForm] = useState(false);\n  const [addingContact, setAddingContact] = useState(false);\n  const [contactName, setContactName] = useState('');\n  const [contactEmail, setContactEmail] = useState('');\n  const [contactPhone, setContactPhone] = useState('');\n  const sites = options.sites.filter(\n    (site) => String(site.client_id) === clientId,\n  );\n  const availableContacts = contacts.filter(\n    (contact) =>\n      String(contact.client_id) === clientId &&\n      (!contact.site_id || (siteId && String(contact.site_id) === siteId)),\n  );\n  async function addContact() {\n    if (!clientId || contactName.trim().length < 2 || !contactEmail.trim()) {\n      onError('Select an organization and enter the contact name and email.');\n      return;\n    }\n    setAddingContact(true);\n    onError('');\n    try {\n      const contact = (await request('/changes/contacts', {\n        method: 'POST',\n        body: JSON.stringify({\n          clientId,\n          siteId: siteId || undefined,\n          name: contactName.trim(),\n          email: contactEmail.trim(),\n          phone: contactPhone.trim() || undefined,\n        }),\n      })) as Row;\n      setContacts((current) => [...current, contact]);\n      setSelectedContacts((current) => [\n        ...new Set([...current, String(contact.id)]),\n      ]);\n      setContactToAdd('');\n      setShowContactForm(false);\n      setContactName('');\n      setContactEmail('');\n      setContactPhone('');\n    } catch (error) {\n      onError((error as Error).message);\n    } finally {\n      setAddingContact(false);\n    }\n  }\n  return (\n    <form className=\"panel change-form\" onSubmit={submit}>\n      <label>\n        Start from a saved plan\n        <select\n          value={selectedTemplate}\n          disabled={busy || templateSaving || templateDeleting}\n          onChange={(e) => {\n            setSelectedTemplate(e.target.value);\n            setTemplateNotice('');\n            const template = templates.find((t) => t.id === e.target.value);\n            const form = e.currentTarget.form;\n            if (!template || !form) return;\n            applyChangePlanToForm(form, template.plan ?? {\n              description: template.description,\n              category: template.category,\n              implementationPlan: template.implementation_plan,\n              testPlan: template.test_plan,\n              rollbackPlan: template.rollback_plan,\n            });\n          }}\n        >\n          <option value=\"\">Start without a template</option>\n          {templates.map((t) => (\n            <option value={t.id} key={t.id}>\n              {t.name}\n            </option>\n          ))}\n        </select>\n      </label>\n      <small className=\"hint\">Templates fill the change details and plans. Choose the organisation, client and owner for this request, and review the planned dates.</small>\n      {canSaveChangePlanDirectly(user.roles) ? <div className=\"form-actions\"><button type=\"button\" className=\"secondary\" disabled={!selectedTemplate || busy || templateSaving || templateDeleting} onClick={async () => {\n        const template = templates.find(item => item.id === selectedTemplate);\n        if (!template || !window.confirm(`Delete template “${template.name}”? Existing changes will not be affected.`)) return;\n        setTemplateDeleting(true); setTemplateNotice(''); onError('');\n        try {\n          const isPlan = template.id.startsWith('plan:');\n          const id = isPlan ? template.id.slice(5) : template.id;\n          await request(`/changes/templates/${encodeURIComponent(id)}?source=${isPlan ? 'plan' : 'legacy'}`, { method: 'DELETE' });\n          setTemplates(current => current.filter(item => item.id !== template.id));\n          setSelectedTemplate(''); setTemplateNotice('Template deleted. Existing changes are unchanged.');\n        } catch (error) { onError((error as Error).message); }\n        finally { setTemplateDeleting(false); }\n      }}>{templateDeleting ? 'Deleting template…' : 'Delete template'}</button></div> : null}\n      {templateNotice ? <p className=\"notice\" role=\"status\">{templateNotice}</p> : null}\n      <fieldset disabled={busy || templateSaving} className=\"form-grid\">\n        <label>\n          Organization\n          <select\n            required\n            name=\"clientId\"\n            value={clientId}\n            onChange={(event) => {\n              setClientId(event.target.value);\n              setSiteId('');\n              setSelectedContacts([]);\n              setContactToAdd('');\n            }}\n          >\n            <option value=\"\">Select…</option>\n            <Opts items={options.clients} />\n          </select>\n        </label>\n        <label>\n          Site\n          <select\n            name=\"siteId\"\n            value={siteId}\n            disabled={!clientId}\n            onChange={(event) => {\n              setSiteId(event.target.value);\n              setSelectedContacts([]);\n              setContactToAdd('');\n            }}\n          >\n            <option value=\"\">None</option>\n            <Opts items={sites} />\n          </select>\n        </label>\n        <label>\n          Lead department\n          <select name=\"departmentId\">\n            <option value=\"\">None</option>\n            <Opts items={options.departments} />\n          </select>\n        </label>\n        <label>\n          Owner\n          <select name=\"ownerUserId\">\n            <option value=\"\">Me</option>\n            <Opts items={options.users} />\n          </select>\n        </label>\n        <label className=\"wide\">\n          Change title\n          <input required minLength={3} maxLength={200} name=\"title\" />\n        </label>\n        <label className=\"wide\">\n          Description\n          <textarea required rows={4} name=\"description\" />\n        </label>\n        <label>\n          Category\n          <select required name=\"category\">\n            {options.categories.map((x) => (\n              <option key={x} value={x}>{label(x)}</option>\n            ))}\n          </select>\n        </label>\n        <label>\n          Change type\n          <select required name=\"changeType\">\n            {options.types.map((x) => (\n              <option key={x} value={x}>{label(x)}</option>\n            ))}\n          </select>\n        </label>\n        <label>\n          Risk\n          <select required name=\"risk\">\n            {options.risks.map((x) => (\n              <option key={x} value={x}>{label(x)}</option>\n            ))}\n          </select>\n        </label>\n        <label>\n          Expected downtime (minutes)\n          <input\n            type=\"number\"\n            min=\"0\"\n            name=\"downtimeMinutes\"\n            defaultValue=\"0\"\n          />\n        </label>\n        <label>\n          Outage expected\n          <select name=\"outageExpected\">\n            <option value=\"false\">No</option>\n            <option value=\"true\">Yes</option>\n          </select>\n        </label>\n        <label>\n          Notify client\n          <select name=\"clientNotificationEnabled\">\n            <option value=\"false\">No</option>\n            <option value=\"true\">Yes, where approved</option>\n          </select>\n        </label>\n        <label>\n          Planned start\n          <input type=\"datetime-local\" name=\"plannedStart\" />\n        </label>\n        <label>\n          Planned end\n          <input type=\"datetime-local\" name=\"plannedEnd\" />\n        </label>\n        {[\n          ['impact', 'Impact assessment'],\n          ['reason', 'Reason for change'],\n          ['businessJustification', 'Business justification'],\n          ['implementationPlan', 'Implementation plan'],\n          ['testPlan', 'Testing and validation plan'],\n          ['rollbackPlan', 'Rollback plan'],\n          ['communicationPlan', 'Communication plan'],\n        ].map(([n, l]) => (\n          <label className=\"wide\" key={n}>\n            {l}\n            <textarea required={n !== 'communicationPlan'} rows={3} name={n} />\n          </label>\n        ))}\n        <section className=\"wide change-stakeholder-editor\">\n          <h2>Stakeholders</h2>\n          <p className=\"hint\">\n            Select client-side contacts from the chosen organization. Vendors or\n            other external participants can be entered as an email or as Name\n            &lt;email@example.com&gt;, separated by commas or new lines. These\n            contacts are recorded on the change; CAB sends no email.\n          </p>\n          {selectedContacts.map((contactId) => (\n            <input\n              key={contactId}\n              type=\"hidden\"\n              name=\"stakeholderContactIds\"\n              value={contactId}\n            />\n          ))}\n          <div className=\"stakeholder-picker\">\n            <label>\n              Existing client contact\n              <select\n                value={contactToAdd}\n                disabled={!clientId}\n                onChange={(event) => setContactToAdd(event.target.value)}\n              >\n                <option value=\"\">\n                  {clientId\n                    ? 'Select a contact…'\n                    : 'Select an organization first'}\n                </option>\n                {availableContacts\n                  .filter(\n                    (contact) => !selectedContacts.includes(String(contact.id)),\n                  )\n                  .map((contact) => (\n                    <option key={String(contact.id)} value={String(contact.id)}>\n                      {String(contact.name)} · {String(contact.email)}\n                      {contact.site_id ? ' · Selected site' : ''}\n                    </option>\n                  ))}\n              </select>\n            </label>\n            <button\n              type=\"button\"\n              className=\"secondary\"\n              disabled={!contactToAdd}\n              onClick={() => {\n                setSelectedContacts((current) => [\n                  ...new Set([...current, contactToAdd]),\n                ]);\n                setContactToAdd('');\n              }}\n            >\n              Add stakeholder\n            </button>\n            <button\n              type=\"button\"\n              className=\"secondary\"\n              disabled={!clientId}\n              onClick={() => setShowContactForm((current) => !current)}\n            >\n              {showContactForm ? 'Cancel new contact' : '+ Add new contact'}\n            </button>\n          </div>\n          {selectedContacts.length ? (\n            <div className=\"selected-stakeholders\">\n              <h3>Selected stakeholders</h3>\n              {selectedContacts.map((contactId) => {\n                const contact = contacts.find(\n                  (item) => String(item.id) === contactId,\n                );\n                return (\n                  <div key={contactId}>\n                    <span>\n                      <strong>{String(contact?.name ?? 'Contact')}</strong>\n                      <small>{String(contact?.email ?? '')}</small>\n                    </span>\n                    <button\n                      type=\"button\"\n                      className=\"stakeholder-remove\"\n                      onClick={() =>\n                        setSelectedContacts((current) =>\n                          current.filter((id) => id !== contactId),\n                        )\n                      }\n                    >\n                      Remove\n                    </button>\n                  </div>\n                );\n              })}\n            </div>\n          ) : (\n            <p className=\"empty\">No stakeholder selected yet.</p>\n          )}\n          {clientId && showContactForm ? (\n            <div className=\"inline-contact-editor\">\n              <h3>Add a new client contact</h3>\n              <p className=\"hint\">\n                The contact is saved for this organization and the selected\n                site. Leave Site as None to create an organization-wide contact.\n              </p>\n              <div className=\"form-grid\">\n                <label>\n                  Contact name\n                  <input\n                    value={contactName}\n                    maxLength={200}\n                    onChange={(event) => setContactName(event.target.value)}\n                  />\n                </label>\n                <label>\n                  Email\n                  <input\n                    type=\"email\"\n                    value={contactEmail}\n                    maxLength={320}\n                    onChange={(event) => setContactEmail(event.target.value)}\n                  />\n                </label>\n                <label>\n                  Phone (optional)\n                  <input\n                    value={contactPhone}\n                    maxLength={50}\n                    onChange={(event) => setContactPhone(event.target.value)}\n                  />\n                </label>\n                <div className=\"form-actions\">\n                  <button\n                    type=\"button\"\n                    className=\"secondary\"\n                    disabled={addingContact}\n                    onClick={() => void addContact()}\n                  >\n                    {addingContact ? 'Adding…' : '+ Add and select contact'}\n                  </button>\n                </div>\n              </div>\n            </div>\n          ) : null}\n          <label>\n            External stakeholders\n            <textarea\n              name=\"externalStakeholders\"\n              rows={3}\n              placeholder={\n                'Client Contact <contact@example.com>\\nvendor@example.com'\n              }\n            />\n          </label>\n        </section>\n        <label className=\"wide\">\n          Supporting attachments\n          <input\n            type=\"file\"\n            name=\"attachments\"\n            multiple\n            accept=\".pdf,.zip,.docx,.xlsx,.gif,.jpg,.jpeg,.png,.csv,.txt\"\n          />\n          <small>Up to 10 files, maximum 5 MB each.</small>\n        </label>\n        <div className=\"wide form-actions\">\n          <Link className=\"secondary\" href={`/changes?workspace=${encodeURIComponent(workspace)}`}>\n            Cancel\n          </Link>\n          {canSaveChangePlanDirectly(user.roles) ? <button type=\"button\" className=\"secondary\" disabled={busy || templateSaving} onClick={async event => {\n            const form = event.currentTarget.form; if (!form) return;\n            setTemplateSaving(true); onError('');\n            try {\n              const plan = changePlanFromForm(new FormData(form));\n              const result = await request('/changes/templates', { method: 'POST', body: JSON.stringify({ ...plan, name: plan.title }) });\n              onTemplateSaved(result as { status: string });\n            } catch (error) { onError((error as Error).message); }\n            finally { setTemplateSaving(false); }\n          }}>{templateSaving ? 'Saving template…' : 'Save template'}</button> : null}\n          <button className=\"primary\" disabled={busy || templateSaving}>\n            {busy ? 'Saving…' : 'Create draft change'}\n          </button>\n        </div>\n      </fieldset>\n    </form>\n  );\n}\nfunction ChangeDetail({\n  readOnly,\n  detail,\n  options,\n  busy,\n  submit,\n}: {\n  detail: {\n    change?: Row;\n    teams?: Row[];\n    tasks?: Row[];\n    approvals?: Row[];\n    updates?: Row[];\n    links?: Row[];\n    history?: Row[];\n    communications?: Row[];\n    stakeholders?: Row[];\n    attachments?: Row[];\n  };\n  options: Options;\n  busy: boolean;\n  readOnly: boolean;\n  submit: (p: string, b: Row, m?: string) => Promise<Row | undefined>;\n}) {\n  const c = detail.change!;\n  const id = String(c.id);\n  const [tab, setTab] = useState('overview');\n  const form =\n    (handler: (f: FormData) => Promise<Row | undefined>) =>\n    async (e: FormEvent<HTMLFormElement>) => {\n      e.preventDefault();\n      const element = e.currentTarget;\n      const saved = await handler(new FormData(element));\n      if (saved) element.reset();\n    };\n  return (\n    <>\n      <section className=\"change-hero panel\">\n        <div>\n          <span className={`pill priority-${String(c.risk).toLowerCase()}`}>\n            {label(c.risk)} risk\n          </span>\n          <span className=\"pill\">{label(c.change_type)}</span>\n          <span className={`pill change-status-${String(c.status).toLowerCase()}`}>{label(c.status)}</span>\n          <h2>{String(c.title)}</h2>\n          <p>{String(c.description)}</p>\n        </div>\n        <div>\n          <strong>Planned window</strong>\n          <span>\n            {date(c.planned_start)}\n            <br />\n            to {date(c.planned_end)}\n          </span>\n        </div>\n      </section>\n      <nav className=\"record-tabs\">\n        {[\n          'overview',\n          'approvals',\n          'tasks & teams',\n          'stakeholders & files',\n          'updates',\n          'communications',\n          'history',\n        ].map((x) => (\n          <button\n            key={x}\n            className={tab === x ? 'active' : ''}\n            onClick={() => setTab(x)}\n          >\n            {label(x)}\n          </button>\n        ))}\n      </nav>\n      {tab === 'overview' ? (\n        <div className=\"change-grid\">\n          <section className=\"panel detail-list\">\n            <h2>Assessment and control plan</h2>\n            {[\n              ['Category', c.category],\n              ['Impact', c.impact],\n              ['Reason', c.reason],\n              ['Business justification', c.business_justification],\n              ['Implementation', c.implementation_plan],\n              ['Testing', c.test_plan],\n              ['Rollback', c.rollback_plan],\n              ['Communication', c.communication_plan],\n            ].map(([k, v]) => (\n              <div key={String(k)}>\n                <strong>{String(k)}</strong>\n                <p>{String(v || 'Not provided')}</p>\n              </div>\n            ))}\n          </section>\n          <div className=\"change-controls-stack\">\n            {!readOnly && (\n              <ExpandablePanel title=\"Move workflow\" className=\"\">\n                <form\n                  onSubmit={form((f) =>\n                    submit(\n                      `/changes/${id}/status`,\n                      {\n                        status: f.get('status'),\n                        note: f.get('note'),\n                        overrideReason: f.get('overrideReason') || undefined,\n                      },\n                      'PATCH',\n                    ),\n                  )}\n                >\n                  <label>\n                    Next status\n                    <select name=\"status\">\n                      {options.statuses.map((s) => (\n                        <option key={s} value={s}>{label(s)}</option>\n                      ))}\n                    </select>\n                  </label>\n                  <label>\n                    Control note\n                    <textarea name=\"note\" rows={3} />\n                  </label>\n                  <label>\n                    Conflict override reason (administrator / Change Manager\n                    only)\n                    <textarea\n                      name=\"overrideReason\"\n                      rows={2}\n                      minLength={10}\n                      maxLength={2000}\n                      placeholder=\"Leave empty unless overriding a scheduling conflict or blackout.\"\n                    />\n                  </label>\n                  <button className=\"primary\" disabled={busy}>\n                    Update status\n                  </button>\n                </form>\n              </ExpandablePanel>\n            )}\n            <ExpandablePanel title=\"Linked incidents\">\n              {detail.links?.map((x) => (\n                <p key={String(x.ticket_id)}>\n                  {String(x.ticket_number)} · {String(x.subject)}\n                </p>\n              ))}\n              {!readOnly && (\n                <form\n                  onSubmit={form((f) =>\n                    submit(`/changes/${id}/tickets`, {\n                      ticketId: f.get('ticketId'),\n                    }),\n                  )}\n                >\n                  <label>\n                    Link ticket\n                    <select required name=\"ticketId\">\n                      <option value=\"\">Select…</option>\n                      {options.tickets.map((x) => (\n                        <option key={String(x.id)} value={String(x.id)}>\n                          {String(x.ticket_number)} · {String(x.subject)}\n                        </option>\n                      ))}\n                    </select>\n                  </label>\n                  <button className=\"primary\">Link ticket</button>\n                </form>\n              )}\n            </ExpandablePanel>\n          </div>\n        </div>\n      ) : null}\n      {tab === 'approvals' ? (\n        <section className=\"panel\">\n          <h2>Approval path</h2>\n          {detail.approvals?.map((a) => (\n            <article className=\"work-item\" key={String(a.id)}>\n              <div>\n                <strong>{String(a.approver_name ?? a.department_name)}</strong>\n                <span>\n                  {label(a.status)} · Sequence {String(a.sequence)} · Revision{' '}\n                  {String(a.revision)} {a.cab_group_id ? '· CAB' : ''}\n                </span>\n              </div>\n              {a.status === 'PENDING' &&\n              a.revision === c.revision &&\n              c.status === 'AWAITING_APPROVAL' ? (\n                !readOnly && (\n                  <form\n                    onSubmit={form((f) =>\n                      submit(\n                        `/changes/${id}/approvals/${String(a.id)}`,\n                        { status: f.get('status'), note: f.get('note') },\n                        'PATCH',\n                      ),\n                    )}\n                  >\n                    <select name=\"status\">\n                      <option value=\"APPROVED\">{label('APPROVED')}</option>\n                      <option value=\"REJECTED\">{label('REJECTED')}</option>\n                      <option value=\"CHANGES_REQUESTED\">{label('CHANGES_REQUESTED')}</option>\n                    </select>\n                    <input required name=\"note\" placeholder=\"Decision note\" />\n                    <button className=\"secondary\">Record decision</button>\n                  </form>\n                )\n              ) : (\n                <p>{String(a.decision_note ?? '')}</p>\n              )}\n            </article>\n          ))}\n          {!readOnly && (\n            <form\n              className=\"inline-form\"\n              onSubmit={form((f) =>\n                submit(`/changes/${id}/approvals`, {\n                  approverUserId: f.get('approverUserId') || undefined,\n                  departmentId: f.get('departmentId') || undefined,\n                  sequence: Number(f.get('sequence') || 1),\n                  required: true,\n                }),\n              )}\n            >\n              <select name=\"approverUserId\">\n                <option value=\"\">Individual approver</option>\n                <Opts items={options.users} />\n              </select>\n              <select name=\"departmentId\">\n                <option value=\"\">Department approver</option>\n                <Opts items={options.departments} />\n              </select>\n              <input type=\"number\" min=\"1\" defaultValue=\"1\" name=\"sequence\" />\n              <button className=\"primary\">Add approval</button>\n            </form>\n          )}\n        </section>\n      ) : null}\n      {tab === 'tasks & teams' ? (\n        <section className=\"panel\">\n          <h2>Implementation teams and tasks</h2>\n          {detail.teams?.map((t) => (\n            <span className=\"pill\" key={String(t.department_id)}>\n              {String(t.department_name)} · {label(t.role)}\n            </span>\n          ))}\n          {!readOnly && (\n            <form\n              className=\"inline-form\"\n              onSubmit={form((f) =>\n                submit(`/changes/${id}/teams`, {\n                  departmentId: f.get('departmentId'),\n                  role: f.get('role'),\n                }),\n              )}\n            >\n              <select required name=\"departmentId\">\n                <option value=\"\">Department…</option>\n                <Opts items={options.departments} />\n              </select>\n              <select name=\"role\">\n                <option value=\"IMPLEMENTER\">{label('IMPLEMENTER')}</option>\n                <option value=\"LEAD\">{label('LEAD')}</option>\n                <option value=\"REVIEWER\">{label('REVIEWER')}</option>\n              </select>\n              <button className=\"secondary\">Add team</button>\n            </form>\n          )}\n          {detail.tasks?.map((t) => (\n            <article className=\"work-item\" key={String(t.id)}>\n              <div>\n                <strong>{String(t.title)}</strong>\n                <span>\n                  {String(t.assigned_name ?? t.department_name ?? 'Unassigned')}{' '}\n                  · {label(t.status)}\n                </span>\n              </div>\n              {!readOnly && (\n                <form\n                  onSubmit={form((f) =>\n                    submit(\n                      `/changes/${id}/tasks/${String(t.id)}`,\n                      {\n                        status: f.get('status'),\n                        updateNote: f.get('updateNote'),\n                      },\n                      'PATCH',\n                    ),\n                  )}\n                >\n                  <select name=\"status\" defaultValue={String(t.status)}>\n                    <option value=\"TODO\">{label('TODO')}</option>\n                    <option value=\"IN_PROGRESS\">{label('IN_PROGRESS')}</option>\n                    <option value=\"BLOCKED\">{label('BLOCKED')}</option>\n                    <option value=\"COMPLETED\">{label('COMPLETED')}</option>\n                    <option value=\"WAIVED\">{label('WAIVED')}</option>\n                  </select>\n                  <input name=\"updateNote\" placeholder=\"Progress update\" />\n                  <button className=\"secondary\">Update</button>\n                </form>\n              )}\n            </article>\n          ))}\n          {!readOnly && (\n            <form\n              className=\"inline-form\"\n              onSubmit={form((f) =>\n                submit(`/changes/${id}/tasks`, {\n                  title: f.get('title'),\n                  instructions: f.get('instructions'),\n                  departmentId: f.get('departmentId') || undefined,\n                  assignedUserId: f.get('assignedUserId') || undefined,\n                  dueAt: f.get('dueAt') || undefined,\n                }),\n              )}\n            >\n              <input required name=\"title\" placeholder=\"Task title\" />\n              <input name=\"instructions\" placeholder=\"Instructions\" />\n              <select name=\"departmentId\">\n                <option value=\"\">Department</option>\n                <Opts items={options.departments} />\n              </select>\n              <select name=\"assignedUserId\">\n                <option value=\"\">Assignee</option>\n                <Opts items={options.users} />\n              </select>\n              <input type=\"datetime-local\" name=\"dueAt\" />\n              <button className=\"primary\">Add task</button>\n            </form>\n          )}\n        </section>\n      ) : null}\n      {tab === 'stakeholders & files' ? (\n        <div className=\"change-grid\">\n          <section className=\"panel\">\n            <h2>Stakeholders</h2>\n            <p className=\"hint\">\n              Stakeholders are client-side contacts for the selected\n              organization. Additional external participants are recorded by\n              email; neither option grants staff portal access.\n            </p>\n            {detail.stakeholders?.length ? (\n              detail.stakeholders.map((stakeholder) => (\n                <article className=\"work-item\" key={String(stakeholder.id)}>\n                  <div>\n                    <strong>\n                      {String(\n                        stakeholder.contact_name ??\n                          stakeholder.legacy_user_name ??\n                          stakeholder.external_name ??\n                          stakeholder.external_email,\n                      )}\n                    </strong>\n                    <span>\n                      {label(stakeholder.stakeholder_role)}\n                      {stakeholder.contact_email ||\n                      stakeholder.legacy_user_email ||\n                      stakeholder.external_email\n                        ? ` · ${String(stakeholder.contact_email ?? stakeholder.legacy_user_email ?? stakeholder.external_email)}`\n                        : ''}\n                    </span>\n                  </div>\n                </article>\n              ))\n            ) : (\n              <p className=\"empty\">No additional stakeholders yet.</p>\n            )}\n            {!readOnly && (\n              <form\n                className=\"inline-form\"\n                onSubmit={form((f) =>\n                  submit(`/changes/${id}/stakeholders`, {\n                    contactId: f.get('contactId') || undefined,\n                    externalName: f.get('externalName') || undefined,\n                    externalEmail: f.get('externalEmail') || undefined,\n                    role: f.get('role'),\n                  }),\n                )}\n              >\n                <select name=\"contactId\">\n                  <option value=\"\">Client contact</option>\n                  <Opts\n                    items={options.contacts.filter(\n                      (contact) =>\n                        String(contact.client_id) === String(c.client_id) &&\n                        (!contact.site_id ||\n                          String(contact.site_id) === String(c.site_id)),\n                    )}\n                  />\n                </select>\n                <input name=\"externalName\" placeholder=\"External name\" />\n                <input\n                  type=\"email\"\n                  name=\"externalEmail\"\n                  placeholder=\"External email\"\n                />\n                <select name=\"role\" defaultValue=\"STAKEHOLDER\">\n                  <option value=\"STAKEHOLDER\">{label('STAKEHOLDER')}</option>\n                  <option value=\"BUSINESS_CONTACT\">{label('BUSINESS_CONTACT')}</option>\n                  <option value=\"TECHNICAL_CONTACT\">{label('TECHNICAL_CONTACT')}</option>\n                  <option value=\"OBSERVER\">{label('OBSERVER')}</option>\n                </select>\n                <button className=\"primary\">Add stakeholder</button>\n              </form>\n            )}\n          </section>\n          <ExpandablePanel title=\"Attachments and evidence\" className=\"\">\n            <p className=\"hint\">\n              Attach implementation plans, screenshots, validation evidence or\n              rollback documentation. Maximum 5 MB per file.\n            </p>\n            {detail.attachments?.length ? (\n              detail.attachments.map((file) => (\n                <a\n                  className=\"attachment\"\n                  key={String(file.id)}\n                  href={`/api/changes/${id}/attachments/${String(file.id)}`}\n                >\n                  <strong>{String(file.file_name)}</strong>\n                  <small>\n                    {Math.ceil(Number(file.size_bytes) / 1024)} KB ·{' '}\n                    {String(file.uploaded_by ?? 'System')}\n                  </small>\n                </a>\n              ))\n            ) : (\n              <p className=\"empty\">No change evidence attached yet.</p>\n            )}\n            {!readOnly && (\n              <form\n                onSubmit={(event) => {\n                  event.preventDefault();\n                  const element = event.currentTarget;\n                  const file = new FormData(element).get('attachment');\n                  if (!(file instanceof File) || !file.size) return;\n                  if (file.size > 5 * 1024 * 1024) {\n                    element.reset();\n                    return;\n                  }\n                  void fileToBase64(file).then(async (contentBase64) => {\n                    await submit(`/changes/${id}/attachments`, {\n                      fileName: file.name,\n                      contentType: file.type || 'application/octet-stream',\n                      contentBase64,\n                    });\n                    element.reset();\n                  });\n                }}\n              >\n                <label>\n                  Add attachment\n                  <input\n                    required\n                    type=\"file\"\n                    name=\"attachment\"\n                    accept=\".pdf,.zip,.docx,.xlsx,.gif,.jpg,.jpeg,.png,.csv,.txt\"\n                  />\n                </label>\n                <button className=\"primary\" disabled={busy}>\n                  Upload file\n                </button>\n              </form>\n            )}\n          </ExpandablePanel>\n        </div>\n      ) : null}\n      {tab === 'updates' ? (\n        <section className=\"panel\">\n          <h2>Team updates</h2>\n          {!readOnly && (\n            <form\n              onSubmit={form((f) =>\n                submit(`/changes/${id}/updates`, {\n                  updateType: f.get('updateType'),\n                  body: f.get('body'),\n                }),\n              )}\n            >\n              <select name=\"updateType\">\n                <option value=\"INTERNAL\">{label('INTERNAL')}</option>\n                <option value=\"IMPLEMENTATION\">{label('IMPLEMENTATION')}</option>\n                <option value=\"VALIDATION\">{label('VALIDATION')}</option>\n                <option value=\"CLIENT_COMMUNICATION\">{label('CLIENT_COMMUNICATION')}</option>\n              </select>\n              <textarea\n                required\n                name=\"body\"\n                rows={4}\n                placeholder=\"Record an update or evidence…\"\n              />\n              <button className=\"primary\">Add update</button>\n            </form>\n          )}\n          {detail.updates?.map((u) => (\n            <article className=\"timeline-item\" key={String(u.id)}>\n              <strong>\n                {label(u.update_type)} · {String(u.author_name)}\n              </strong>\n              <p>{String(u.body)}</p>\n              <small>{date(u.created_at)}</small>\n            </article>\n          ))}\n        </section>\n      ) : null}\n      {tab === 'communications' ? (\n        <section className=\"panel\">\n          <h2>Communication history</h2>\n          <p className=\"hint\">\n            CAB email delivery is disabled. Record progress and decisions in\n            Updates so reviewers and stakeholders with portal access can follow\n            the change.\n          </p>\n          {detail.communications?.map((x) => (\n            <article className=\"work-item\" key={String(x.id)}>\n              <div>\n                <strong>{String(x.subject)}</strong>\n                <span>\n                  {label(x.status)} ·{' '}\n                  {String((x.recipient_emails as string[])?.length ?? 0)}{' '}\n                  recipients\n                </span>\n              </div>\n            </article>\n          ))}\n        </section>\n      ) : null}\n      {tab === 'history' ? (\n        <section className=\"panel\">\n          <h2>Immutable change history</h2>\n          {detail.history?.map((h) => (\n            <article className=\"timeline-item\" key={String(h.id)}>\n              <strong>{label(h.event)}</strong>\n              <p>\n                {String(h.actor_name ?? 'System')} · {date(h.created_at)}\n              </p>\n            </article>\n          ))}\n        </section>\n      ) : null}\n    </>\n  );\n}\n","after":"import { hasFullAccess } from './role-access';\nimport ProfileIdentity from './profile-identity';\nimport { uiLabel } from './ui-label';\n'use client';\nimport './change-detail-layout.css';\nimport { reviewedFetch } from './reviewed-fetch';\nimport ExpandablePanel from './expandable-panel';\nimport AdministrationOversight from './administration-oversight';\nimport WorkspaceNavigation from './workspace-navigation';\nimport { extensionLinks } from './workspace-navigation-data';\nimport MailTimeline from './mail-timeline';\nimport ChangeGovernancePanel from './change-governance-panel';\nimport ChangeReviewWorkspace from './change-review-workspace';\nimport ChangePlanTemplateDialog from './change-plan-template-dialog';\nimport ChangeTemplatePicker from './change-template-picker';\nimport { canCreateChangePlan, canSaveChangePlanDirectly, changePlanFromForm, applyChangePlanToForm, type ChangePlanData, type SavedChangePlan } from './change-plan-model';\nimport { canReviewChangeRequests } from './change-review-access';\nimport type {\n  ChangeTemplate,\n  GovernanceConfig,\n} from './admin/change-governance/governance-administration';\nimport Link from '../navigation/link';\nimport { FormEvent, useCallback, useEffect, useState } from 'react';\nimport { useRouter, useSearchParams } from '../navigation/hooks';\nimport BrandMark from './brand-mark';\nimport NotificationCenter from './notification-center';\nimport UiIcon, { type IconName } from './ui-icon';\n\ntype Row = Record<string, unknown>;\ninterface Session {\n  csrfToken: string;\n  user: {\n    id: string;\n    displayName: string;\n    roles: string[];\n    permissions?: string[];\n    workScope?: string;\n    workspace?: string;\n    changeAccess?: string;\n  };\n}\ninterface Options {\n  clients: Row[];\n  sites: Row[];\n  contacts: Row[];\n  departments: Row[];\n  users: Row[];\n  tickets: Row[];\n  categories: string[];\n  types: string[];\n  risks: string[];\n  statuses: string[];\n  emailEnabled: boolean;\n  changeMailbox: string;\n}\nconst label = uiLabel;\nconst date = (v: unknown) => (v ? new Date(String(v)).toLocaleString() : '—');\nasync function fileToBase64(file: File) {\n  return new Promise<string>((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onload = () => resolve(String(reader.result).split(',')[1] ?? '');\n    reader.onerror = () => reject(new Error('Unable to read attachment.'));\n    reader.readAsDataURL(file);\n  });\n}\nfunction parseExternalStakeholder(value: string) {\n  const match = value.match(/^(.+?)\\s*<([^<>]+)>$/);\n  return match\n    ? { name: match[1].trim(), email: match[2].trim(), role: 'STAKEHOLDER' }\n    : { email: value, role: 'STAKEHOLDER' };\n}\n\nexport default function ChangeWorkspace({\n  view = 'dashboard',\n  changeId,\n}: {\n  view?: 'dashboard' | 'new' | 'detail';\n  changeId?: string;\n}) {\n  const router = useRouter();\n  const searchParams = useSearchParams();\n  const [session, setSession] = useState<Session>();\n  const reviewingChanges = view === 'dashboard' && searchParams.get('reviewCM') === '1';\n  const canReviewCM = canReviewChangeRequests(session?.user.roles ?? []);\n  const [menu, setMenu] = useState(false);\n  const [options, setOptions] = useState<Options>();\n  const [data, setData] = useState<Row>();\n  const [error, setError] = useState('');\n  const [notice, setNotice] = useState('');\n  const [busy, setBusy] = useState(false);\n  const [revision, setRevision] = useState(0);\n  const [creatingTemplate, setCreatingTemplate] = useState(false);\n  const [templateRevision, setTemplateRevision] = useState(0);\n  function templateSaved(result: { status: string }) {\n    setCreatingTemplate(false); setTemplateRevision(value => value + 1);\n    setNotice(result.status === 'APPROVED' ? 'Template saved and available in saved plans.' : 'Template submitted for approval. Your team lead, manager or administrator can review it in Review CM > Templates.');\n  }\n  const request = useCallback(\n    async (path: string, init?: RequestInit) => {\n      const r = await reviewedFetch(`/api${path}`, {\n        ...init,\n        cache: 'no-store',\n        headers: {\n          ...(init?.body ? { 'content-type': 'application/json' } : {}),\n          ...(session ? { 'x-csrf-token': session.csrfToken } : {}),\n          ...init?.headers,\n        },\n      });\n      const body = await r.json().catch(() => ({}));\n      if (!r.ok) throw new Error(body.error?.message ?? 'Request failed.');\n      return body;\n    },\n    [session],\n  );\n  useEffect(() => {\n    let live = true;\n    void fetch('/api/auth/me', { cache: 'no-store' })\n      .then(async (r) => {\n        if (!r.ok) throw new Error('Sign in to open Change Management.');\n        const s = (await r.json()) as Session;\n        if (s.user.changeAccess === 'NONE' && !hasFullAccess(s.user.roles))\n          throw new Error(\n            'Change Management has not been enabled for your account.',\n          );\n        if (live) setSession(s);\n      })\n      .catch((e) => live && setError(e.message));\n    return () => {\n      live = false;\n    };\n  }, []);\n  useEffect(() => {\n    if (!session) return;\n    if (reviewingChanges) { setError(''); setNotice(''); return; }\n    let live = true;\n    void Promise.all([\n      request('/changes/options'),\n      view === 'dashboard'\n        ? Promise.all([\n            request('/changes/dashboard'),\n            request('/changes?pageSize=50'),\n            request('/changes/calendar'),\n          ]).then(([dashboard, list, calendar]) => ({\n            dashboard,\n            list,\n            calendar,\n          }))\n        : view === 'detail' && changeId\n          ? request(`/changes/${changeId}`)\n          : Promise.resolve({}),\n    ])\n      .then(([o, d]) => {\n        if (live) {\n          setOptions(o as Options);\n          setData(d as Row);\n        }\n      })\n      .catch((e) => live && setError(e.message));\n    return () => {\n      live = false;\n    };\n  }, [session, request, view, changeId, revision, reviewingChanges]);\n  async function submit(path: string, payload: Row, method = 'POST') {\n    setBusy(true);\n    setError('');\n    try {\n      const result = (await request(path, {\n        method,\n        body: JSON.stringify(payload),\n      })) as Row;\n      setNotice('Saved successfully.');\n      setRevision((x) => x + 1);\n      return result;\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(false);\n    }\n  }\n  async function create(e: FormEvent<HTMLFormElement>) {\n    e.preventDefault();\n    const f = new FormData(e.currentTarget);\n    const attachmentFiles = f\n      .getAll('attachments')\n      .filter(\n        (value): value is File => value instanceof File && value.size > 0,\n      );\n    if (\n      attachmentFiles.length > 10 ||\n      attachmentFiles.some((file) => file.size > 5 * 1024 * 1024)\n    ) {\n      setError('Add up to 10 attachments, with a maximum of 5 MB per file.');\n      return;\n    }\n    const attachments = await Promise.all(\n      attachmentFiles.map(async (file) => ({\n        fileName: file.name,\n        contentType: file.type || 'application/octet-stream',\n        contentBase64: await fileToBase64(file),\n      })),\n    );\n    const externalStakeholders = String(f.get('externalStakeholders') ?? '')\n      .split(/[\\n,;]+/)\n      .map((entry) => entry.trim())\n      .filter(Boolean)\n      .map(parseExternalStakeholder);\n    const result = await submit('/changes', {\n      clientId: f.get('clientId'),\n      siteId: f.get('siteId') || undefined,\n      departmentId: f.get('departmentId') || undefined,\n      title: f.get('title'),\n      description: f.get('description'),\n      category: f.get('category'),\n      changeType: f.get('changeType'),\n      risk: f.get('risk'),\n      impact: f.get('impact'),\n      outageExpected: f.get('outageExpected') === 'true',\n      downtimeMinutes: Number(f.get('downtimeMinutes') || 0),\n      reason: f.get('reason'),\n      businessJustification: f.get('businessJustification'),\n      implementationPlan: f.get('implementationPlan'),\n      testPlan: f.get('testPlan'),\n      rollbackPlan: f.get('rollbackPlan'),\n      communicationPlan: f.get('communicationPlan'),\n      clientNotificationEnabled: f.get('clientNotificationEnabled') === 'true',\n      ownerUserId: f.get('ownerUserId') || undefined,\n      plannedStart: f.get('plannedStart')\n        ? new Date(String(f.get('plannedStart'))).toISOString()\n        : undefined,\n      plannedEnd: f.get('plannedEnd')\n        ? new Date(String(f.get('plannedEnd'))).toISOString()\n        : undefined,\n      stakeholderContactIds: f.getAll('stakeholderContactIds').map(String),\n      externalStakeholders,\n      attachments,\n    });\n    if (result?.id) router.push(`/changes/${String(result.id)}?workspace=${encodeURIComponent(selectedWorkspace)}`);\n  }\n  async function logout() {\n    await request('/auth/logout', { method: 'POST' });\n    router.push('/');\n  }\n  const detail = data as\n    | {\n        change?: Row;\n        teams?: Row[];\n        tasks?: Row[];\n        approvals?: Row[];\n        updates?: Row[];\n        links?: Row[];\n        history?: Row[];\n        communications?: Row[];\n      }\n    | undefined;\n  const isAdmin = hasFullAccess(session?.user.roles) ?? false;\n  const readOnly = session?.user.workspace === 'admin';\n  const isManagement =\n    session?.user.roles.includes('MANAGER') ||\n    session?.user.roles.includes('TEAM_LEAD');\n  const allowed = (permission: string) =>\n    isAdmin || session?.user.permissions?.includes(permission);\n  const requestedWorkspace = searchParams.get('workspace');\n  const selectedWorkspace = requestedWorkspace && ['operations', 'management', 'admin'].includes(requestedWorkspace)\n    ? requestedWorkspace\n    : session?.user.workspace ?? (isAdmin ? 'admin' : isManagement ? 'management' : 'operations');\n  const inAdminWorkspace = selectedWorkspace === 'admin';\n  const inManagementWorkspace = selectedWorkspace === 'management';\n  const portalNav: [string, IconName, string][] = inAdminWorkspace\n    ? [\n        ['/admin', 'dashboard', 'Overview'],\n        ['/admin/tickets', 'tickets', 'Tickets'],\n        ['/admin/sla', 'sla', 'SLA Management'],\n        ['/admin/reports', 'reports', 'Reports & Analytics'],\n        ['/admin/users', 'users', 'People & Permissions'],\n        ['/admin/clients', 'clients', 'Clients'],\n        ['/admin/contacts', 'contacts', 'Contacts'],\n        ['/admin/sites', 'sites', 'Sites'],\n        ['/admin/categories', 'categories', 'Categories'],\n        ['/admin/tags', 'tags', 'Tags'],\n        ['/admin/audit-logs', 'audit', 'Audit History'],\n        ['/changes', 'change', 'Change Management'],\n      ]\n    : inManagementWorkspace\n      ? [\n          ['/management', 'dashboard', 'Dashboard'],\n          ['/management/tickets', 'tickets', 'Tickets'],\n          ...(allowed('CATEGORY_MANAGE') ? [['/admin/categories', 'categories', 'Categories'] as [string, IconName, string]] : []),\n          ...(allowed('TAGS_MANAGE') ? [['/admin/tags', 'tags', 'Tags'] as [string, IconName, string]] : []),\n          ...(allowed('AUDIT_VIEW') ? [['/admin/audit-logs', 'audit', 'Audit History'] as [string, IconName, string]] : []),\n          ...(allowed('SLA_MANAGE') || session?.user.roles.includes('TEAM_LEAD')\n            ? ([['/management/sla', 'sla', 'SLA Management']] as [\n                string,\n                IconName,\n                string,\n              ][])\n            : []),\n          ...(allowed('REPORTS_VIEW')\n            ? ([['/management/reports', 'reports', 'Reports & Analytics']] as [\n                string,\n                IconName,\n                string,\n              ][])\n            : []),\n          ['/changes', 'change', 'Change Management'],\n        ]\n      : [\n          ['/operations', 'dashboard', 'Dashboard'],\n          ['/operations/tickets', 'tickets', 'My Tickets'],\n          ...(allowed('TICKETS_TEAM_VIEW')\n            ? ([['/operations/team-tickets', 'team', 'Team Tickets']] as [\n                string,\n                IconName,\n                string,\n              ][])\n            : []),\n          ...(['INTERNAL', 'BOTH', 'ALL'].includes(\n            session?.user.workScope ?? '',\n          )\n            ? ([\n                ['/operations/internal-tickets', 'tickets', 'Internal Tickets'],\n              ] as [string, IconName, string][])\n            : []),\n          ['/changes', 'change', 'Change Management'],\n        ];\n  return (\n    <div className=\"admin-shell ticket-shell change-shell\">\n      <a className=\"skip-link\" href=\"#main\">\n        Skip to content\n      </a>\n      <aside className={`sidebar ${menu ? 'open' : ''}`}>\n        <Link className=\"brand\" href=\"/\">\n          <BrandMark />\n          <span>\n            ASTRA<small>Ticketing System</small>\n          </span>\n        </Link>\n        <p className=\"nav-label\">\n          {inAdminWorkspace\n            ? 'ADMINISTRATION'\n            : inManagementWorkspace\n              ? 'MANAGEMENT'\n              : 'TECHNICIAN PORTAL'}\n        </p>\n        <nav aria-label=\"Portal navigation\">\n          <WorkspaceNavigation\n            links={[...portalNav, ...extensionLinks(session?.user)]}\n            activeHref=\"/changes\"\n            workspace={selectedWorkspace}\n            onNavigate={() => setMenu(false)}\n          />\n        </nav>\n        <div className=\"sidebar-bottom\">\n          <Link href=\"/\">\n            <UiIcon name=\"switch\" /> Switch workspace\n          </Link>\n          <small>\n            <i /> Service desk online\n          </small>\n        </div>\n      </aside>\n      <div className=\"workspace\">\n        <header className=\"topbar\">\n          <button\n            type=\"button\"\n            className=\"menu-button secondary\"\n            aria-expanded={menu}\n            aria-label=\"Toggle navigation\"\n            onClick={() => setMenu(!menu)}\n          >\n            ☰\n          </button>\n          <span className=\"breadcrumb\">\n            <Link href=\"/\" className=\"workspace-home-link\">\n              {inAdminWorkspace\n                ? 'Administration'\n                : inManagementWorkspace\n                  ? 'Management'\n                  : 'Technician Portal'}\n            </Link>{' '}\n            <span>/</span> Change Management\n          </span>\n          {session ? (\n            <div className=\"account\">\n              <ProfileIdentity name={session.user.displayName} workspace={inAdminWorkspace ? 'admin' : inManagementWorkspace ? 'management' : 'operations'} />\n              <NotificationCenter\n                csrfToken={session.csrfToken}\n                ticketBase={\n                  inAdminWorkspace\n                    ? '/admin/ticket'\n                    : inManagementWorkspace\n                      ? '/management/tickets'\n                      : '/operations/tickets'\n                }\n              />\n              <button className=\"secondary\" onClick={() => void logout()}>\n                Sign out\n              </button>\n            </div>\n          ) : null}\n        </header>\n        <main id=\"main\" className=\"content change-workspace-content\">\n          <div className=\"page-heading\">\n            <div>\n              <p className=\"eyebrow\">CONTROLLED SERVICE CHANGE</p>\n              <h1>\n                {reviewingChanges ? 'Review CM' : readOnly && view === 'new'\n                  ? 'Change administration'\n                  : view === 'new'\n                    ? 'Raise a change'\n                    : view === 'detail'\n                      ? `${String(detail?.change?.change_number ?? 'Change record')}`\n                      : 'Change Management'}\n              </h1>\n              <p>\n                {reviewingChanges\n                  ? 'Review waiting change requests and find previous review decisions.'\n                  : readOnly\n                  ? 'Review change records, approvals and history. Configure policy in Service administration.'\n                  : view === 'dashboard'\n                    ? 'Plan, approve, coordinate and verify infrastructure and service changes.'\n                    : view === 'new'\n                      ? 'Document impact, implementation, testing and rollback before approval.'\n                      : 'One controlled record for plan, approvals, teams and evidence.'}\n              </p>\n            </div>\n            <div className=\"v38-row\">\n              {session && view === 'new' && canCreateChangePlan(session.user.roles) ? <button type=\"button\" className=\"primary\" onClick={() => setCreatingTemplate(true)}>New template</button> : null}\n              {session && canReviewCM && view !== 'new' && !reviewingChanges ? <Link className=\"secondary\" href={`/changes?workspace=${encodeURIComponent(selectedWorkspace)}&reviewCM=1`}>Review CM</Link> : null}\n              {reviewingChanges ? <Link className=\"secondary\" href={`/changes?workspace=${encodeURIComponent(selectedWorkspace)}`}>Back to changes</Link> : null}\n              {session && !readOnly && view !== 'new' ? (\n                <Link className=\"primary\" href={`/changes/new?workspace=${encodeURIComponent(selectedWorkspace)}`}>\n                  + Raise change\n                </Link>\n              ) : null}\n            </div>\n          </div>\n          {error ? (\n            <div className=\"notice error\" role=\"alert\">\n              {error}\n            </div>\n          ) : null}\n          {notice ? <div className=\"notice success\">{notice}</div> : null}\n          {session && reviewingChanges ? canReviewCM ? <ChangeReviewWorkspace csrfToken={session.csrfToken} workspace={selectedWorkspace} /> : <p className=\"notice error\" role=\"alert\">Team Lead, Manager or Administrator access is required to review change requests.</p> : null}\n          {readOnly && !reviewingChanges ? <AdministrationOversight /> : null}\n          {view === 'dashboard' && !reviewingChanges ? (\n            <ChangeDashboard data={data} workspace={selectedWorkspace} />\n          ) : null}\n          {session && creatingTemplate ? <ChangePlanTemplateDialog roles={session.user.roles} request={request} onClose={() => setCreatingTemplate(false)} onSaved={templateSaved} /> : null}\n          {view === 'new' && session && !readOnly && options ? (\n            <ChangeForm\n              user={session.user}\n              templateRevision={templateRevision}\n              onTemplateSaved={templateSaved}\n              workspace={selectedWorkspace}\n              options={options}\n              submit={create}\n              busy={busy}\n              request={request}\n              onError={setError}\n            />\n          ) : null}\n          {view === 'detail' && detail?.change && options ? (\n            <ChangeDetail\n              readOnly={readOnly}\n              detail={detail}\n              options={options}\n              busy={busy}\n              submit={submit}\n            />\n          ) : null}\n          {view === 'detail' && detail?.change && session ? (\n            <>\n              <ChangeGovernancePanel\n                change={detail.change}\n                user={session.user}\n                revision={revision}\n                request={request}\n                submit={submit}\n              />\n              <MailTimeline\n                kind=\"changes\"\n                id={String(detail.change.id)}\n                revision={revision}\n              />\n            </>\n          ) : null}\n        </main>\n      </div>\n    </div>\n  );\n}\n\nfunction ChangeDashboard({\n  data,\n  workspace,\n}: {\n  data?: Row;\n  workspace?: string;\n}) {\n  const d = data?.dashboard as Row | undefined;\n  const list = (data?.list as { items?: Row[] } | undefined)?.items ?? [];\n  const calendar = (data?.calendar as Row[] | undefined) ?? [];\n  return (\n    <>\n      <section className=\"metric-grid\">\n        <Metric name=\"Total changes\" value={d?.total} />\n        <Metric name=\"Awaiting approval\" value={d?.awaiting_approval} />\n        <Metric name=\"Scheduled\" value={d?.scheduled} />\n        <Metric name=\"In progress\" value={d?.in_progress} />\n        <Metric name=\"High risk open\" value={d?.high_risk} />\n      </section>\n      <section className=\"change-grid\">\n        <div className=\"panel\">\n          <div className=\"section-heading\">\n            <h2>Change register</h2>\n            <span>{list.length} visible</span>\n          </div>\n          <div className=\"table-wrap\">\n            <table className=\"change-register-table\">\n              <thead>\n                <tr>\n                  <th>Change</th>\n                  <th>Type</th>\n                  <th>Risk</th>\n                  <th>Status</th>\n                  <th>Owner</th>\n                  <th>Window</th>\n                </tr>\n              </thead>\n              <tbody>\n                {list.map((c) => (\n                  <tr key={String(c.id)}>\n                    <td>\n                      <Link\n                        href={`/changes/${String(c.id)}${workspace ? `?workspace=${encodeURIComponent(workspace)}` : ''}`}\n                      >\n                        <strong>{String(c.change_number)}</strong>\n                        <small>{String(c.title)}</small>\n                      </Link>\n                    </td>\n                    <td><span className=\"pill change-type\">{label(c.change_type)}</span></td>\n                    <td>\n                      <span\n                        className={`pill priority-${String(c.risk).toLowerCase()}`}\n                      >\n                        {label(c.risk)}\n                      </span>\n                    </td>\n                    <td>\n                      <span className={`pill change-status-${String(c.status).toLowerCase()}`}>{label(c.status)}</span>\n                    </td>\n                    <td>{String(c.owner_name)}</td>\n                    <td><span className=\"change-window\">{c.planned_start ? date(c.planned_start) : 'Not scheduled'}</span></td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        </div>\n        <div className=\"panel\">\n          <h2>Change calendar</h2>\n          {calendar.length ? (\n            calendar.map((c) => (\n              <Link\n                className=\"calendar-change\"\n                key={String(c.id)}\n                href={`/changes/${String(c.id)}${workspace ? `?workspace=${encodeURIComponent(workspace)}` : ''}`}\n              >\n                <strong>\n                  {String(c.change_number)} · {String(c.title)}\n                </strong>\n                <span>\n                  {date(c.planned_start)} → {date(c.planned_end)}\n                </span>\n              </Link>\n            ))\n          ) : (\n            <p className=\"empty\">No planned change windows yet.</p>\n          )}\n        </div>\n      </section>\n    </>\n  );\n}\nfunction Metric({ name, value }: { name: string; value: unknown }) {\n  return (\n    <div className=\"metric-card\">\n      <span>{name}</span>\n      <strong>{String(value ?? 0)}</strong>\n    </div>\n  );\n}\nfunction Opts({ items }: { items: Row[] }) {\n  return (\n    <>\n      {items.map((x) => (\n        <option key={String(x.id)} value={String(x.id)}>\n          {String(x.name)}\n        </option>\n      ))}\n    </>\n  );\n}\nexport function ChangeForm({\n  user,\n  templateRevision,\n  onTemplateSaved,\n  workspace,\n  options,\n  submit,\n  busy,\n  request,\n  onError,\n}: {\n  options: Options;\n  submit: (e: FormEvent<HTMLFormElement>) => void;\n  busy: boolean;\n  request: (path: string, init?: RequestInit) => Promise<unknown>;\n  onError: (message: string) => void;\n  workspace: string;\n  user: Session['user'];\n  templateRevision: number;\n  onTemplateSaved: (result: { status: string }) => void;\n}) {\n  const [templateSaving, setTemplateSaving] = useState(false);\n  const [selectedTemplate, setSelectedTemplate] = useState('');\n  const [templateDeleting, setTemplateDeleting] = useState(false);\n  const [templateNotice, setTemplateNotice] = useState('');\n  const [clientId, setClientId] = useState('');\n  const [templates, setTemplates] = useState<(ChangeTemplate & { plan?: ChangePlanData })[]>([]);\n  useEffect(() => {\n    let live = true;\n    void Promise.all([request('/change-governance'), request('/changes/templates')])\n      .then(([c, saved]) => {\n        if (!live) return;\n        const plans = (saved as { items: SavedChangePlan[] }).items.map(item => {\n          const plan: ChangePlanData = typeof item.plan === 'string' ? JSON.parse(item.plan) : item.plan;\n          return { id: `plan:${item.id}`, name: item.name, category: plan.category, description: plan.description, implementation_plan: plan.implementationPlan, test_plan: plan.testPlan, rollback_plan: plan.rollbackPlan, active: true, plan };\n        });\n        setTemplates([...(c as GovernanceConfig).templates.filter(t => t.active), ...plans]);\n      })\n      .catch((e) => onError(e.message));\n    return () => {\n      live = false;\n    };\n  }, [request, onError, templateRevision]);\n  const [siteId, setSiteId] = useState('');\n  const [contacts, setContacts] = useState(options.contacts);\n  const [selectedContacts, setSelectedContacts] = useState<string[]>([]);\n  const [contactToAdd, setContactToAdd] = useState('');\n  const [showContactForm, setShowContactForm] = useState(false);\n  const [addingContact, setAddingContact] = useState(false);\n  const [contactName, setContactName] = useState('');\n  const [contactEmail, setContactEmail] = useState('');\n  const [contactPhone, setContactPhone] = useState('');\n  const sites = options.sites.filter(\n    (site) => String(site.client_id) === clientId,\n  );\n  const availableContacts = contacts.filter(\n    (contact) =>\n      String(contact.client_id) === clientId &&\n      (!contact.site_id || (siteId && String(contact.site_id) === siteId)),\n  );\n  async function addContact() {\n    if (!clientId || contactName.trim().length < 2 || !contactEmail.trim()) {\n      onError('Select an organization and enter the contact name and email.');\n      return;\n    }\n    setAddingContact(true);\n    onError('');\n    try {\n      const contact = (await request('/changes/contacts', {\n        method: 'POST',\n        body: JSON.stringify({\n          clientId,\n          siteId: siteId || undefined,\n          name: contactName.trim(),\n          email: contactEmail.trim(),\n          phone: contactPhone.trim() || undefined,\n        }),\n      })) as Row;\n      setContacts((current) => [...current, contact]);\n      setSelectedContacts((current) => [\n        ...new Set([...current, String(contact.id)]),\n      ]);\n      setContactToAdd('');\n      setShowContactForm(false);\n      setContactName('');\n      setContactEmail('');\n      setContactPhone('');\n    } catch (error) {\n      onError((error as Error).message);\n    } finally {\n      setAddingContact(false);\n    }\n  }\n  return (\n    <form className=\"panel change-form\" onSubmit={submit}>\n      <ChangeTemplatePicker templates={templates} value={selectedTemplate} canDelete={canSaveChangePlanDirectly(user.roles)} disabled={busy || templateSaving || templateDeleting}\n        onChange={(id, form) => {\n          setSelectedTemplate(id); setTemplateNotice('');\n          const template = templates.find(item => item.id === id);\n          if (!template || !form) return;\n          applyChangePlanToForm(form, template.plan ?? { description: template.description, category: template.category, implementationPlan: template.implementation_plan, testPlan: template.test_plan, rollbackPlan: template.rollback_plan });\n        }}\n        onDelete={async id => {\n          const template = templates.find(item => item.id === id);\n          if (!template || !window.confirm(`Delete template “${template.name}”? Existing changes will not be affected.`)) return;\n          setTemplateDeleting(true); setTemplateNotice(''); onError('');\n          try {\n            const isPlan = template.id.startsWith('plan:');\n            const templateId = isPlan ? template.id.slice(5) : template.id;\n            await request(`/changes/templates/${encodeURIComponent(templateId)}?source=${isPlan ? 'plan' : 'legacy'}`, { method: 'DELETE' });\n            setTemplates(current => current.filter(item => item.id !== template.id));\n            setSelectedTemplate(current => current === template.id ? '' : current);\n            setTemplateNotice('Template deleted. Existing changes are unchanged.');\n          } catch (error) { onError((error as Error).message); }\n          finally { setTemplateDeleting(false); }\n        }} />\n      <small className=\"hint\">Templates fill the change details and plans. Choose the organisation, client and owner for this request, and review the planned dates.</small>\n      {templateNotice ? <p className=\"notice\" role=\"status\">{templateNotice}</p> : null}\n      <fieldset disabled={busy || templateSaving} className=\"form-grid\">\n        <label>\n          Organization\n          <select\n            required\n            name=\"clientId\"\n            value={clientId}\n            onChange={(event) => {\n              setClientId(event.target.value);\n              setSiteId('');\n              setSelectedContacts([]);\n              setContactToAdd('');\n            }}\n          >\n            <option value=\"\">Select…</option>\n            <Opts items={options.clients} />\n          </select>\n        </label>\n        <label>\n          Site\n          <select\n            name=\"siteId\"\n            value={siteId}\n            disabled={!clientId}\n            onChange={(event) => {\n              setSiteId(event.target.value);\n              setSelectedContacts([]);\n              setContactToAdd('');\n            }}\n          >\n            <option value=\"\">None</option>\n            <Opts items={sites} />\n          </select>\n        </label>\n        <label>\n          Lead department\n          <select name=\"departmentId\">\n            <option value=\"\">None</option>\n            <Opts items={options.departments} />\n          </select>\n        </label>\n        <label>\n          Owner\n          <select name=\"ownerUserId\">\n            <option value=\"\">Me</option>\n            <Opts items={options.users} />\n          </select>\n        </label>\n        <label className=\"wide\">\n          Change title\n          <input required minLength={3} maxLength={200} name=\"title\" />\n        </label>\n        <label className=\"wide\">\n          Description\n          <textarea required rows={4} name=\"description\" />\n        </label>\n        <label>\n          Category\n          <select required name=\"category\">\n            {options.categories.map((x) => (\n              <option key={x} value={x}>{label(x)}</option>\n            ))}\n          </select>\n        </label>\n        <label>\n          Change type\n          <select required name=\"changeType\">\n            {options.types.map((x) => (\n              <option key={x} value={x}>{label(x)}</option>\n            ))}\n          </select>\n        </label>\n        <label>\n          Risk\n          <select required name=\"risk\">\n            {options.risks.map((x) => (\n              <option key={x} value={x}>{label(x)}</option>\n            ))}\n          </select>\n        </label>\n        <label>\n          Expected downtime (minutes)\n          <input\n            type=\"number\"\n            min=\"0\"\n            name=\"downtimeMinutes\"\n            defaultValue=\"0\"\n          />\n        </label>\n        <label>\n          Outage expected\n          <select name=\"outageExpected\">\n            <option value=\"false\">No</option>\n            <option value=\"true\">Yes</option>\n          </select>\n        </label>\n        <label>\n          Notify client\n          <select name=\"clientNotificationEnabled\">\n            <option value=\"false\">No</option>\n            <option value=\"true\">Yes, where approved</option>\n          </select>\n        </label>\n        <label>\n          Planned start\n          <input type=\"datetime-local\" name=\"plannedStart\" />\n        </label>\n        <label>\n          Planned end\n          <input type=\"datetime-local\" name=\"plannedEnd\" />\n        </label>\n        {[\n          ['impact', 'Impact assessment'],\n          ['reason', 'Reason for change'],\n          ['businessJustification', 'Business justification'],\n          ['implementationPlan', 'Implementation plan'],\n          ['testPlan', 'Testing and validation plan'],\n          ['rollbackPlan', 'Rollback plan'],\n          ['communicationPlan', 'Communication plan'],\n        ].map(([n, l]) => (\n          <label className=\"wide\" key={n}>\n            {l}\n            <textarea required={n !== 'communicationPlan'} rows={3} name={n} />\n          </label>\n        ))}\n        <section className=\"wide change-stakeholder-editor\">\n          <h2>Stakeholders</h2>\n          <p className=\"hint\">\n            Select client-side contacts from the chosen organization. Vendors or\n            other external participants can be entered as an email or as Name\n            &lt;email@example.com&gt;, separated by commas or new lines. These\n            contacts are recorded on the change; CAB sends no email.\n          </p>\n          {selectedContacts.map((contactId) => (\n            <input\n              key={contactId}\n              type=\"hidden\"\n              name=\"stakeholderContactIds\"\n              value={contactId}\n            />\n          ))}\n          <div className=\"stakeholder-picker\">\n            <label>\n              Existing client contact\n              <select\n                value={contactToAdd}\n                disabled={!clientId}\n                onChange={(event) => setContactToAdd(event.target.value)}\n              >\n                <option value=\"\">\n                  {clientId\n                    ? 'Select a contact…'\n                    : 'Select an organization first'}\n                </option>\n                {availableContacts\n                  .filter(\n                    (contact) => !selectedContacts.includes(String(contact.id)),\n                  )\n                  .map((contact) => (\n                    <option key={String(contact.id)} value={String(contact.id)}>\n                      {String(contact.name)} · {String(contact.email)}\n                      {contact.site_id ? ' · Selected site' : ''}\n                    </option>\n                  ))}\n              </select>\n            </label>\n            <button\n              type=\"button\"\n              className=\"secondary\"\n              disabled={!contactToAdd}\n              onClick={() => {\n                setSelectedContacts((current) => [\n                  ...new Set([...current, contactToAdd]),\n                ]);\n                setContactToAdd('');\n              }}\n            >\n              Add stakeholder\n            </button>\n            <button\n              type=\"button\"\n              className=\"secondary\"\n              disabled={!clientId}\n              onClick={() => setShowContactForm((current) => !current)}\n            >\n              {showContactForm ? 'Cancel new contact' : '+ Add new contact'}\n            </button>\n          </div>\n          {selectedContacts.length ? (\n            <div className=\"selected-stakeholders\">\n              <h3>Selected stakeholders</h3>\n              {selectedContacts.map((contactId) => {\n                const contact = contacts.find(\n                  (item) => String(item.id) === contactId,\n                );\n                return (\n                  <div key={contactId}>\n                    <span>\n                      <strong>{String(contact?.name ?? 'Contact')}</strong>\n                      <small>{String(contact?.email ?? '')}</small>\n                    </span>\n                    <button\n                      type=\"button\"\n                      className=\"stakeholder-remove\"\n                      onClick={() =>\n                        setSelectedContacts((current) =>\n                          current.filter((id) => id !== contactId),\n                        )\n                      }\n                    >\n                      Remove\n                    </button>\n                  </div>\n                );\n              })}\n            </div>\n          ) : (\n            <p className=\"empty\">No stakeholder selected yet.</p>\n          )}\n          {clientId && showContactForm ? (\n            <div className=\"inline-contact-editor\">\n              <h3>Add a new client contact</h3>\n              <p className=\"hint\">\n                The contact is saved for this organization and the selected\n                site. Leave Site as None to create an organization-wide contact.\n              </p>\n              <div className=\"form-grid\">\n                <label>\n                  Contact name\n                  <input\n                    value={contactName}\n                    maxLength={200}\n                    onChange={(event) => setContactName(event.target.value)}\n                  />\n                </label>\n                <label>\n                  Email\n                  <input\n                    type=\"email\"\n                    value={contactEmail}\n                    maxLength={320}\n                    onChange={(event) => setContactEmail(event.target.value)}\n                  />\n                </label>\n                <label>\n                  Phone (optional)\n                  <input\n                    value={contactPhone}\n                    maxLength={50}\n                    onChange={(event) => setContactPhone(event.target.value)}\n                  />\n                </label>\n                <div className=\"form-actions\">\n                  <button\n                    type=\"button\"\n                    className=\"secondary\"\n                    disabled={addingContact}\n                    onClick={() => void addContact()}\n                  >\n                    {addingContact ? 'Adding…' : '+ Add and select contact'}\n                  </button>\n                </div>\n              </div>\n            </div>\n          ) : null}\n          <label>\n            External stakeholders\n            <textarea\n              name=\"externalStakeholders\"\n              rows={3}\n              placeholder={\n                'Client Contact <contact@example.com>\\nvendor@example.com'\n              }\n            />\n          </label>\n        </section>\n        <label className=\"wide\">\n          Supporting attachments\n          <input\n            type=\"file\"\n            name=\"attachments\"\n            multiple\n            accept=\".pdf,.zip,.docx,.xlsx,.gif,.jpg,.jpeg,.png,.csv,.txt\"\n          />\n          <small>Up to 10 files, maximum 5 MB each.</small>\n        </label>\n        <div className=\"wide form-actions\">\n          <Link className=\"secondary\" href={`/changes?workspace=${encodeURIComponent(workspace)}`}>\n            Cancel\n          </Link>\n          {canSaveChangePlanDirectly(user.roles) ? <button type=\"button\" className=\"secondary\" disabled={busy || templateSaving} onClick={async event => {\n            const form = event.currentTarget.form; if (!form) return;\n            setTemplateSaving(true); onError('');\n            try {\n              const plan = changePlanFromForm(new FormData(form));\n              const result = await request('/changes/templates', { method: 'POST', body: JSON.stringify({ ...plan, name: plan.title }) });\n              onTemplateSaved(result as { status: string });\n            } catch (error) { onError((error as Error).message); }\n            finally { setTemplateSaving(false); }\n          }}>{templateSaving ? 'Saving template…' : 'Save template'}</button> : null}\n          <button className=\"primary\" disabled={busy || templateSaving}>\n            {busy ? 'Saving…' : 'Create draft change'}\n          </button>\n        </div>\n      </fieldset>\n    </form>\n  );\n}\nfunction ChangeDetail({\n  readOnly,\n  detail,\n  options,\n  busy,\n  submit,\n}: {\n  detail: {\n    change?: Row;\n    teams?: Row[];\n    tasks?: Row[];\n    approvals?: Row[];\n    updates?: Row[];\n    links?: Row[];\n    history?: Row[];\n    communications?: Row[];\n    stakeholders?: Row[];\n    attachments?: Row[];\n  };\n  options: Options;\n  busy: boolean;\n  readOnly: boolean;\n  submit: (p: string, b: Row, m?: string) => Promise<Row | undefined>;\n}) {\n  const c = detail.change!;\n  const id = String(c.id);\n  const [tab, setTab] = useState('overview');\n  const form =\n    (handler: (f: FormData) => Promise<Row | undefined>) =>\n    async (e: FormEvent<HTMLFormElement>) => {\n      e.preventDefault();\n      const element = e.currentTarget;\n      const saved = await handler(new FormData(element));\n      if (saved) element.reset();\n    };\n  return (\n    <>\n      <section className=\"change-hero panel\">\n        <div>\n          <span className={`pill priority-${String(c.risk).toLowerCase()}`}>\n            {label(c.risk)} risk\n          </span>\n          <span className=\"pill\">{label(c.change_type)}</span>\n          <span className={`pill change-status-${String(c.status).toLowerCase()}`}>{label(c.status)}</span>\n          <h2>{String(c.title)}</h2>\n          <p>{String(c.description)}</p>\n        </div>\n        <div>\n          <strong>Planned window</strong>\n          <span>\n            {date(c.planned_start)}\n            <br />\n            to {date(c.planned_end)}\n          </span>\n        </div>\n      </section>\n      <nav className=\"record-tabs\">\n        {[\n          'overview',\n          'approvals',\n          'tasks & teams',\n          'stakeholders & files',\n          'updates',\n          'communications',\n          'history',\n        ].map((x) => (\n          <button\n            key={x}\n            className={tab === x ? 'active' : ''}\n            onClick={() => setTab(x)}\n          >\n            {label(x)}\n          </button>\n        ))}\n      </nav>\n      {tab === 'overview' ? (\n        <div className=\"change-grid\">\n          <section className=\"panel detail-list\">\n            <h2>Assessment and control plan</h2>\n            {[\n              ['Category', c.category],\n              ['Impact', c.impact],\n              ['Reason', c.reason],\n              ['Business justification', c.business_justification],\n              ['Implementation', c.implementation_plan],\n              ['Testing', c.test_plan],\n              ['Rollback', c.rollback_plan],\n              ['Communication', c.communication_plan],\n            ].map(([k, v]) => (\n              <div key={String(k)}>\n                <strong>{String(k)}</strong>\n                <p>{String(v || 'Not provided')}</p>\n              </div>\n            ))}\n          </section>\n          <div className=\"change-controls-stack\">\n            {!readOnly && (\n              <ExpandablePanel title=\"Move workflow\" className=\"\">\n                <form\n                  onSubmit={form((f) =>\n                    submit(\n                      `/changes/${id}/status`,\n                      {\n                        status: f.get('status'),\n                        note: f.get('note'),\n                        overrideReason: f.get('overrideReason') || undefined,\n                      },\n                      'PATCH',\n                    ),\n                  )}\n                >\n                  <label>\n                    Next status\n                    <select name=\"status\">\n                      {options.statuses.map((s) => (\n                        <option key={s} value={s}>{label(s)}</option>\n                      ))}\n                    </select>\n                  </label>\n                  <label>\n                    Control note\n                    <textarea name=\"note\" rows={3} />\n                  </label>\n                  <label>\n                    Conflict override reason (administrator / Change Manager\n                    only)\n                    <textarea\n                      name=\"overrideReason\"\n                      rows={2}\n                      minLength={10}\n                      maxLength={2000}\n                      placeholder=\"Leave empty unless overriding a scheduling conflict or blackout.\"\n                    />\n                  </label>\n                  <button className=\"primary\" disabled={busy}>\n                    Update status\n                  </button>\n                </form>\n              </ExpandablePanel>\n            )}\n            <ExpandablePanel title=\"Linked incidents\">\n              {detail.links?.map((x) => (\n                <p key={String(x.ticket_id)}>\n                  {String(x.ticket_number)} · {String(x.subject)}\n                </p>\n              ))}\n              {!readOnly && (\n                <form\n                  onSubmit={form((f) =>\n                    submit(`/changes/${id}/tickets`, {\n                      ticketId: f.get('ticketId'),\n                    }),\n                  )}\n                >\n                  <label>\n                    Link ticket\n                    <select required name=\"ticketId\">\n                      <option value=\"\">Select…</option>\n                      {options.tickets.map((x) => (\n                        <option key={String(x.id)} value={String(x.id)}>\n                          {String(x.ticket_number)} · {String(x.subject)}\n                        </option>\n                      ))}\n                    </select>\n                  </label>\n                  <button className=\"primary\">Link ticket</button>\n                </form>\n              )}\n            </ExpandablePanel>\n          </div>\n        </div>\n      ) : null}\n      {tab === 'approvals' ? (\n        <section className=\"panel\">\n          <h2>Approval path</h2>\n          {detail.approvals?.map((a) => (\n            <article className=\"work-item\" key={String(a.id)}>\n              <div>\n                <strong>{String(a.approver_name ?? a.department_name)}</strong>\n                <span>\n                  {label(a.status)} · Sequence {String(a.sequence)} · Revision{' '}\n                  {String(a.revision)} {a.cab_group_id ? '· CAB' : ''}\n                </span>\n              </div>\n              {a.status === 'PENDING' &&\n              a.revision === c.revision &&\n              c.status === 'AWAITING_APPROVAL' ? (\n                !readOnly && (\n                  <form\n                    onSubmit={form((f) =>\n                      submit(\n                        `/changes/${id}/approvals/${String(a.id)}`,\n                        { status: f.get('status'), note: f.get('note') },\n                        'PATCH',\n                      ),\n                    )}\n                  >\n                    <select name=\"status\">\n                      <option value=\"APPROVED\">{label('APPROVED')}</option>\n                      <option value=\"REJECTED\">{label('REJECTED')}</option>\n                      <option value=\"CHANGES_REQUESTED\">{label('CHANGES_REQUESTED')}</option>\n                    </select>\n                    <input required name=\"note\" placeholder=\"Decision note\" />\n                    <button className=\"secondary\">Record decision</button>\n                  </form>\n                )\n              ) : (\n                <p>{String(a.decision_note ?? '')}</p>\n              )}\n            </article>\n          ))}\n          {!readOnly && (\n            <form\n              className=\"inline-form\"\n              onSubmit={form((f) =>\n                submit(`/changes/${id}/approvals`, {\n                  approverUserId: f.get('approverUserId') || undefined,\n                  departmentId: f.get('departmentId') || undefined,\n                  sequence: Number(f.get('sequence') || 1),\n                  required: true,\n                }),\n              )}\n            >\n              <select name=\"approverUserId\">\n                <option value=\"\">Individual approver</option>\n                <Opts items={options.users} />\n              </select>\n              <select name=\"departmentId\">\n                <option value=\"\">Department approver</option>\n                <Opts items={options.departments} />\n              </select>\n              <input type=\"number\" min=\"1\" defaultValue=\"1\" name=\"sequence\" />\n              <button className=\"primary\">Add approval</button>\n            </form>\n          )}\n        </section>\n      ) : null}\n      {tab === 'tasks & teams' ? (\n        <section className=\"panel\">\n          <h2>Implementation teams and tasks</h2>\n          {detail.teams?.map((t) => (\n            <span className=\"pill\" key={String(t.department_id)}>\n              {String(t.department_name)} · {label(t.role)}\n            </span>\n          ))}\n          {!readOnly && (\n            <form\n              className=\"inline-form\"\n              onSubmit={form((f) =>\n                submit(`/changes/${id}/teams`, {\n                  departmentId: f.get('departmentId'),\n                  role: f.get('role'),\n                }),\n              )}\n            >\n              <select required name=\"departmentId\">\n                <option value=\"\">Department…</option>\n                <Opts items={options.departments} />\n              </select>\n              <select name=\"role\">\n                <option value=\"IMPLEMENTER\">{label('IMPLEMENTER')}</option>\n                <option value=\"LEAD\">{label('LEAD')}</option>\n                <option value=\"REVIEWER\">{label('REVIEWER')}</option>\n              </select>\n              <button className=\"secondary\">Add team</button>\n            </form>\n          )}\n          {detail.tasks?.map((t) => (\n            <article className=\"work-item\" key={String(t.id)}>\n              <div>\n                <strong>{String(t.title)}</strong>\n                <span>\n                  {String(t.assigned_name ?? t.department_name ?? 'Unassigned')}{' '}\n                  · {label(t.status)}\n                </span>\n              </div>\n              {!readOnly && (\n                <form\n                  onSubmit={form((f) =>\n                    submit(\n                      `/changes/${id}/tasks/${String(t.id)}`,\n                      {\n                        status: f.get('status'),\n                        updateNote: f.get('updateNote'),\n                      },\n                      'PATCH',\n                    ),\n                  )}\n                >\n                  <select name=\"status\" defaultValue={String(t.status)}>\n                    <option value=\"TODO\">{label('TODO')}</option>\n                    <option value=\"IN_PROGRESS\">{label('IN_PROGRESS')}</option>\n                    <option value=\"BLOCKED\">{label('BLOCKED')}</option>\n                    <option value=\"COMPLETED\">{label('COMPLETED')}</option>\n                    <option value=\"WAIVED\">{label('WAIVED')}</option>\n                  </select>\n                  <input name=\"updateNote\" placeholder=\"Progress update\" />\n                  <button className=\"secondary\">Update</button>\n                </form>\n              )}\n            </article>\n          ))}\n          {!readOnly && (\n            <form\n              className=\"inline-form\"\n              onSubmit={form((f) =>\n                submit(`/changes/${id}/tasks`, {\n                  title: f.get('title'),\n                  instructions: f.get('instructions'),\n                  departmentId: f.get('departmentId') || undefined,\n                  assignedUserId: f.get('assignedUserId') || undefined,\n                  dueAt: f.get('dueAt') || undefined,\n                }),\n              )}\n            >\n              <input required name=\"title\" placeholder=\"Task title\" />\n              <input name=\"instructions\" placeholder=\"Instructions\" />\n              <select name=\"departmentId\">\n                <option value=\"\">Department</option>\n                <Opts items={options.departments} />\n              </select>\n              <select name=\"assignedUserId\">\n                <option value=\"\">Assignee</option>\n                <Opts items={options.users} />\n              </select>\n              <input type=\"datetime-local\" name=\"dueAt\" />\n              <button className=\"primary\">Add task</button>\n            </form>\n          )}\n        </section>\n      ) : null}\n      {tab === 'stakeholders & files' ? (\n        <div className=\"change-grid\">\n          <section className=\"panel\">\n            <h2>Stakeholders</h2>\n            <p className=\"hint\">\n              Stakeholders are client-side contacts for the selected\n              organization. Additional external participants are recorded by\n              email; neither option grants staff portal access.\n            </p>\n            {detail.stakeholders?.length ? (\n              detail.stakeholders.map((stakeholder) => (\n                <article className=\"work-item\" key={String(stakeholder.id)}>\n                  <div>\n                    <strong>\n                      {String(\n                        stakeholder.contact_name ??\n                          stakeholder.legacy_user_name ??\n                          stakeholder.external_name ??\n                          stakeholder.external_email,\n                      )}\n                    </strong>\n                    <span>\n                      {label(stakeholder.stakeholder_role)}\n                      {stakeholder.contact_email ||\n                      stakeholder.legacy_user_email ||\n                      stakeholder.external_email\n                        ? ` · ${String(stakeholder.contact_email ?? stakeholder.legacy_user_email ?? stakeholder.external_email)}`\n                        : ''}\n                    </span>\n                  </div>\n                </article>\n              ))\n            ) : (\n              <p className=\"empty\">No additional stakeholders yet.</p>\n            )}\n            {!readOnly && (\n              <form\n                className=\"inline-form\"\n                onSubmit={form((f) =>\n                  submit(`/changes/${id}/stakeholders`, {\n                    contactId: f.get('contactId') || undefined,\n                    externalName: f.get('externalName') || undefined,\n                    externalEmail: f.get('externalEmail') || undefined,\n                    role: f.get('role'),\n                  }),\n                )}\n              >\n                <select name=\"contactId\">\n                  <option value=\"\">Client contact</option>\n                  <Opts\n                    items={options.contacts.filter(\n                      (contact) =>\n                        String(contact.client_id) === String(c.client_id) &&\n                        (!contact.site_id ||\n                          String(contact.site_id) === String(c.site_id)),\n                    )}\n                  />\n                </select>\n                <input name=\"externalName\" placeholder=\"External name\" />\n                <input\n                  type=\"email\"\n                  name=\"externalEmail\"\n                  placeholder=\"External email\"\n                />\n                <select name=\"role\" defaultValue=\"STAKEHOLDER\">\n                  <option value=\"STAKEHOLDER\">{label('STAKEHOLDER')}</option>\n                  <option value=\"BUSINESS_CONTACT\">{label('BUSINESS_CONTACT')}</option>\n                  <option value=\"TECHNICAL_CONTACT\">{label('TECHNICAL_CONTACT')}</option>\n                  <option value=\"OBSERVER\">{label('OBSERVER')}</option>\n                </select>\n                <button className=\"primary\">Add stakeholder</button>\n              </form>\n            )}\n          </section>\n          <ExpandablePanel title=\"Attachments and evidence\" className=\"\">\n            <p className=\"hint\">\n              Attach implementation plans, screenshots, validation evidence or\n              rollback documentation. Maximum 5 MB per file.\n            </p>\n            {detail.attachments?.length ? (\n              detail.attachments.map((file) => (\n                <a\n                  className=\"attachment\"\n                  key={String(file.id)}\n                  href={`/api/changes/${id}/attachments/${String(file.id)}`}\n                >\n                  <strong>{String(file.file_name)}</strong>\n                  <small>\n                    {Math.ceil(Number(file.size_bytes) / 1024)} KB ·{' '}\n                    {String(file.uploaded_by ?? 'System')}\n                  </small>\n                </a>\n              ))\n            ) : (\n              <p className=\"empty\">No change evidence attached yet.</p>\n            )}\n            {!readOnly && (\n              <form\n                onSubmit={(event) => {\n                  event.preventDefault();\n                  const element = event.currentTarget;\n                  const file = new FormData(element).get('attachment');\n                  if (!(file instanceof File) || !file.size) return;\n                  if (file.size > 5 * 1024 * 1024) {\n                    element.reset();\n                    return;\n                  }\n                  void fileToBase64(file).then(async (contentBase64) => {\n                    await submit(`/changes/${id}/attachments`, {\n                      fileName: file.name,\n                      contentType: file.type || 'application/octet-stream',\n                      contentBase64,\n                    });\n                    element.reset();\n                  });\n                }}\n              >\n                <label>\n                  Add attachment\n                  <input\n                    required\n                    type=\"file\"\n                    name=\"attachment\"\n                    accept=\".pdf,.zip,.docx,.xlsx,.gif,.jpg,.jpeg,.png,.csv,.txt\"\n                  />\n                </label>\n                <button className=\"primary\" disabled={busy}>\n                  Upload file\n                </button>\n              </form>\n            )}\n          </ExpandablePanel>\n        </div>\n      ) : null}\n      {tab === 'updates' ? (\n        <section className=\"panel\">\n          <h2>Team updates</h2>\n          {!readOnly && (\n            <form\n              onSubmit={form((f) =>\n                submit(`/changes/${id}/updates`, {\n                  updateType: f.get('updateType'),\n                  body: f.get('body'),\n                }),\n              )}\n            >\n              <select name=\"updateType\">\n                <option value=\"INTERNAL\">{label('INTERNAL')}</option>\n                <option value=\"IMPLEMENTATION\">{label('IMPLEMENTATION')}</option>\n                <option value=\"VALIDATION\">{label('VALIDATION')}</option>\n                <option value=\"CLIENT_COMMUNICATION\">{label('CLIENT_COMMUNICATION')}</option>\n              </select>\n              <textarea\n                required\n                name=\"body\"\n                rows={4}\n                placeholder=\"Record an update or evidence…\"\n              />\n              <button className=\"primary\">Add update</button>\n            </form>\n          )}\n          {detail.updates?.map((u) => (\n            <article className=\"timeline-item\" key={String(u.id)}>\n              <strong>\n                {label(u.update_type)} · {String(u.author_name)}\n              </strong>\n              <p>{String(u.body)}</p>\n              <small>{date(u.created_at)}</small>\n            </article>\n          ))}\n        </section>\n      ) : null}\n      {tab === 'communications' ? (\n        <section className=\"panel\">\n          <h2>Communication history</h2>\n          <p className=\"hint\">\n            CAB email delivery is disabled. Record progress and decisions in\n            Updates so reviewers and stakeholders with portal access can follow\n            the change.\n          </p>\n          {detail.communications?.map((x) => (\n            <article className=\"work-item\" key={String(x.id)}>\n              <div>\n                <strong>{String(x.subject)}</strong>\n                <span>\n                  {label(x.status)} ·{' '}\n                  {String((x.recipient_emails as string[])?.length ?? 0)}{' '}\n                  recipients\n                </span>\n              </div>\n            </article>\n          ))}\n        </section>\n      ) : null}\n      {tab === 'history' ? (\n        <section className=\"panel\">\n          <h2>Immutable change history</h2>\n          {detail.history?.map((h) => (\n            <article className=\"timeline-item\" key={String(h.id)}>\n              <strong>{label(h.event)}</strong>\n              <p>\n                {String(h.actor_name ?? 'System')} · {date(h.created_at)}\n              </p>\n            </article>\n          ))}\n        </section>\n      ) : null}\n    </>\n  );\n}\n"};
const files=[{"path":"ASTRA-Frontend-latest/src/pages/change-template-picker.tsx","content":"import { useEffect, useId, useRef, useState } from 'react';\nimport './change-template-picker.css';\n\nexport function ChangeTemplateChoices({ templates, value, choose, remove, canDelete }: {\n  templates: { id: string; name: string }[]; value: string; choose: (id: string) => void; remove: (id: string) => void; canDelete: boolean;\n}) {\n  return <>\n    <div className=\"change-template-row\"><button className=\"change-template-choice\" type=\"button\" aria-pressed={!value} onClick={() => choose('')}><span>Start without a template</span>{!value ? <span aria-hidden=\"true\">✓</span> : null}</button></div>\n    {templates.map(template => <div key={template.id} className=\"change-template-row\">\n      <button type=\"button\" className=\"change-template-choice\" aria-pressed={value === template.id} onClick={() => choose(template.id)}><span>{template.name}</span>{value === template.id ? <span aria-hidden=\"true\">✓</span> : null}</button>\n      {canDelete ? <button type=\"button\" className=\"change-template-trash\" aria-label={`Delete template ${template.name}`} title={`Delete template ${template.name}`} onClick={() => remove(template.id)}>\n        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.7\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7\" /></svg>\n      </button> : null}\n    </div>)}\n  </>;\n}\n\nexport default function ChangeTemplatePicker({ templates, value, onChange, onDelete, canDelete, disabled }: {\n  templates: { id: string; name: string }[]; value: string; onChange: (id: string, form: HTMLFormElement | null) => void;\n  onDelete: (id: string) => Promise<void>; canDelete: boolean; disabled: boolean;\n}) {\n  const id = useId(); const root = useRef<HTMLDivElement>(null); const trigger = useRef<HTMLButtonElement>(null);\n  const [open, setOpen] = useState(false);\n  useEffect(() => {\n    if (!open) return;\n    const outside = (event: PointerEvent) => { if (event.target instanceof Node && !root.current?.contains(event.target)) setOpen(false); };\n    document.addEventListener('pointerdown', outside);\n    return () => document.removeEventListener('pointerdown', outside);\n  }, [open]);\n  useEffect(() => { if (disabled) setOpen(false); }, [disabled]);\n  function choose(next: string) { onChange(next, trigger.current?.form ?? null); setOpen(false); trigger.current?.focus(); }\n  return <div className=\"change-template-picker\" ref={root} onKeyDown={event => {\n    if (event.key === 'Escape') { event.preventDefault(); setOpen(false); trigger.current?.focus(); }\n  }} onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false); }}>\n    <label id={`${id}-label`} htmlFor={`${id}-trigger`}>Start from a saved plan</label>\n    <button ref={trigger} id={`${id}-trigger`} type=\"button\" className=\"change-template-picker-trigger\" disabled={disabled}\n      aria-expanded={open} aria-haspopup=\"dialog\" aria-controls={`${id}-choices`} onClick={() => setOpen(current => !current)}\n      onKeyDown={event => { if (event.key === 'ArrowDown') { event.preventDefault(); setOpen(true); requestAnimationFrame(() => root.current?.querySelector<HTMLButtonElement>('.change-template-choice')?.focus()); } }}>\n      <span>{templates.find(item => item.id === value)?.name ?? 'Start without a template'}</span><span aria-hidden=\"true\">⌄</span>\n    </button>\n    {open ? <div className=\"change-template-choices\" id={`${id}-choices`} role=\"dialog\" aria-labelledby={`${id}-label`}>\n      <ChangeTemplateChoices templates={templates} value={value} choose={choose} canDelete={canDelete} remove={templateId => { setOpen(false); trigger.current?.focus(); void onDelete(templateId); }} />\n    </div> : null}\n  </div>;\n}\n"},{"path":"ASTRA-Frontend-latest/src/pages/change-template-picker.css","content":".change-template-picker { position: relative; display: grid; gap: 8px; min-width: 0; }\n.change-template-picker > label { font-size: 14px; font-weight: 600; color: var(--spark-muted,#61728d); }\nhtml.spark-ui .change-template-picker-trigger { display: flex; align-items: center; justify-content: space-between; gap: 16px; width: 100%; min-height: 44px; padding: 10px 16px; border: 1px solid var(--line,#dce5f2); border-radius: 10px; background: var(--spark-input-bg,#f7f9fd); color: var(--spark-text,#18244a); text-align: left; font-weight: 400; }\n.change-template-picker-trigger > span:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.change-template-choices { position: absolute; z-index: 50; top: calc(100% + 6px); left: 0; right: 0; max-height: 300px; overflow-y: auto; padding: 6px; border: 1px solid var(--line,#dce5f2); border-radius: 12px; background: var(--spark-surface,#fff); box-shadow: 0 12px 30px #14224920; }\n.change-template-row { display: flex; align-items: center; gap: 4px; border-radius: 8px; }\n.change-template-row:hover { background: var(--spark-input-bg,#f2f6fd); }\nhtml.spark-ui .change-template-choice { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex: 1; min-width: 0; min-height: 42px; border: 0; border-radius: 8px; padding: 10px; background: transparent; color: var(--spark-text,#18244a); text-align: left; font-weight: 600; }\n.change-template-choice > span:first-child { overflow-wrap: anywhere; }\nhtml.spark-ui .change-template-choice[aria-pressed=\"true\"] { background: var(--spark-soft,#edf3ff); }\nhtml.spark-ui .change-template-trash { display: grid; place-items: center; flex: 0 0 36px; width: 36px; height: 36px; margin-right: 4px; padding: 0; border: 0; border-radius: 8px; color: #cf3038; background: transparent; }\nhtml.spark-ui .change-template-trash:hover { background: #fff0f1; }\n.change-template-picker button:focus-visible { outline: 2px solid #3165ee; outline-offset: 2px; }\n"}];
const normalize=s=>s.replace(/\r\n/g,'\n').trimEnd()+'\n';
if(!['--check','--apply'].includes(process.argv[2]))throw Error('Use --check or --apply');
const current=normalize(await fs.readFile(path.join(root,ui.path),'utf8'));if(current!==ui.before&&current!==ui.after)throw Error('STOP: change form differs. No files changed.');
const changes=[[ui.path,ui.after]];for(const item of files){let existing=null;try{existing=normalize(await fs.readFile(path.join(root,item.path),'utf8'));}catch(e){if(e.code!=='ENOENT')throw e;}if(existing!==null&&existing!==item.content)throw Error('STOP: picker source differs. No files changed.');changes.push([item.path,item.content]);}
for(const [target,content]of changes){if(process.argv[2]==='--apply')await fs.writeFile(path.join(root,target),content);console.log((process.argv[2]==='--apply'?'Updated: ':'Checked: ')+target);}
